def invalidate_curriculum_cache():
    global _CURRICULUM_CACHE_EPOCH
    with _CURRICULUM_CACHE_LOCK:
        _CURRICULUM_CACHE.clear()
        # Bumping the epoch discards results from any factory that is mid-flight
        # right now. Without it, a build that started before this write completes
        # afterwards and repopulates the cache with pre-write rows, which would
        # then serve stale authoring data for the rest of the TTL.
        _CURRICULUM_CACHE_EPOCH += 1
    # Generation-based invalidation works with Django's built-in Redis backend
    # without relying on backend-specific delete-pattern APIs. Old generations
    # expire naturally after the normal TTL.
    try:
        cache.add(_CURRICULUM_SHARED_EPOCH_KEY, 0, timeout=None)
        cache.incr(_CURRICULUM_SHARED_EPOCH_KEY)
    except Exception:
        logger.warning('Unable to invalidate shared curriculum cache.', exc_info=True)
    _TABLE_EXISTS_CACHE.clear()


# Whole-table reads memoised for the duration of one payload build. build_programmes()
# calls programme_component_ksb_mapping_count() and programme_learner_ksb_progress()
# once per programme, and each of those re-reads authoring modules, programmes,
# cohorts, groups and ksb_profiles in full. On a remote database that turned a
# ~30-row payload into ~300 round trips (35s per build). The scope is opened only
# around read-only payload assembly and torn down on exit, so a write path never
# reads back rows it just wrote from a stale memo.
_CURRICULUM_READ_SCOPE = threading.local()


@contextlib.contextmanager
def curriculum_read_scope():
    """Deduplicate repeated whole-table curriculum reads inside one build.

    Reentrant: a nested ``with`` reuses the outermost scope, which owns the
    lifetime, so a payload build called from inside another one still sees a
    single set of reads.
    """
    if getattr(_CURRICULUM_READ_SCOPE, 'memo', None) is not None:
        yield
        return
    _CURRICULUM_READ_SCOPE.memo = {}
    try:
        yield
    finally:
        _CURRICULUM_READ_SCOPE.memo = None


def _scope_memo_key(value):
    """Hashable stand-in for a call argument (query params arrive as lists)."""
    if isinstance(value, (list, tuple)):
        return tuple(_scope_memo_key(item) for item in value)
    if isinstance(value, (set, frozenset)):
        return frozenset(_scope_memo_key(item) for item in value)
    if isinstance(value, dict):
        return tuple(sorted((key, _scope_memo_key(item)) for key, item in value.items()))
    return value


def scoped_curriculum_read(fn):
    """Memoise a read-only helper for the current curriculum_read_scope().

    Outside a scope the call passes straight through, so nothing changes for
    write paths or for callers that have not opted in. An argument that cannot
    be reduced to a hashable key also passes straight through rather than
    failing the request.
    """
    @functools.wraps(fn)
    def wrapped(*args, **kwargs):
        memo = getattr(_CURRICULUM_READ_SCOPE, 'memo', None)
        if memo is None:
            return fn(*args, **kwargs)
        try:
            key = (
                fn.__qualname__,
                _scope_memo_key(args),
                _scope_memo_key(tuple(sorted(kwargs.items()))),
            )
            hash(key)
        except TypeError:
            return fn(*args, **kwargs)
        if key not in memo:
            memo[key] = fn(*args, **kwargs)
        return memo[key]
    return wrapped


def shared_curriculum_epoch():
    try:
        cache.add(_CURRICULUM_SHARED_EPOCH_KEY, 0, timeout=None)
        return int(cache.get(_CURRICULUM_SHARED_EPOCH_KEY) or 0)
    except Exception:
        # Redis must never turn a cacheable read into an application outage.
        logger.warning('Unable to read shared curriculum cache epoch.', exc_info=True)
        return 0


def shared_curriculum_cache_key(key, epoch):
    digest = hashlib.sha256(str(key).encode()).hexdigest()
    return f'curriculum:v{epoch}:{digest}'


def cached_curriculum_value(key, factory):
    now = datetime.now().timestamp()
    shared_epoch = shared_curriculum_epoch()
    with _CURRICULUM_CACHE_LOCK:
        entry = _CURRICULUM_CACHE.get(key)
        if entry and entry['expires_at'] > now and entry.get('shared_epoch') == shared_epoch:
            return entry['value']
        epoch = _CURRICULUM_CACHE_EPOCH

    shared_key = shared_curriculum_cache_key(key, shared_epoch)
    try:
        shared_value = cache.get(shared_key)
    except Exception:
        logger.warning('Unable to read shared curriculum payload cache.', exc_info=True)
        shared_value = None
    if shared_value is not None:
        with _CURRICULUM_CACHE_LOCK:
            _CURRICULUM_CACHE[key] = {
                'expires_at': now + CURRICULUM_CACHE_TTL_SECONDS,
                'shared_epoch': shared_epoch,
                'value': shared_value,
            }
        return shared_value

    # Build outside the lock: these factories run multi-table queries that can take
    # seconds on a cold database, and holding the lock would serialise every other
    # cached read behind them. An exception propagates without storing anything, so
    # failures are never cached.
    value = factory()

    with _CURRICULUM_CACHE_LOCK:
        # Only publish if no write invalidated the cache while we were building.
        if epoch == _CURRICULUM_CACHE_EPOCH and shared_epoch == shared_curriculum_epoch():
            _CURRICULUM_CACHE[key] = {
                'expires_at': datetime.now().timestamp() + CURRICULUM_CACHE_TTL_SECONDS,
                'shared_epoch': shared_epoch,
                'value': value,
            }
            try:
                cache.set(shared_key, value, timeout=CURRICULUM_CACHE_TTL_SECONDS)
            except Exception:
                logger.warning('Unable to populate shared curriculum payload cache.', exc_info=True)
    return value


def request_bypasses_curriculum_cache(request):
    cache_control = clean_str(request.headers.get('Cache-Control')).lower()
    pragma = clean_str(request.headers.get('Pragma')).lower()
    return (
        'no-cache' in cache_control
        or 'no-store' in cache_control
        or 'no-cache' in pragma
        or truthy(request.GET.get('skipCache'))
        or clean_str(request.GET.get('_ts'))
    )


def reference_json_response(request, payload):
    """JSON response with a validating ETag, for reference data only.

    Suitable for endpoints whose body depends on nothing but the reference tables:
    no per-user, per-role or per-programme variation. The ETag is derived from the
    serialised body, so it changes exactly when the content does — there is no TTL
    to tune and no way to serve content that is newer than its validator.

    ``Cache-Control: private, no-cache`` makes the browser revalidate every time
    and keeps the payload out of shared caches; a match then costs a 304 with no
    body instead of the full response. Deliberately not ``public``: these endpoints
    sit behind authentication, so a shared cache must not retain them.
    """
    body = json.dumps(payload, cls=DjangoJSONEncoder)
    etag = f'"{hashlib.sha256(body.encode()).hexdigest()[:32]}"'
    if_none_match = clean_str(request.headers.get('If-None-Match'))
    if if_none_match and etag in [value.strip() for value in if_none_match.split(',')]:
        response = HttpResponseNotModified()
    else:
        response = HttpResponse(body, content_type='application/json')
    response['ETag'] = etag
    response['Cache-Control'] = 'private, no-cache'
    return response


def rows_as_dicts(cursor):
    columns = [col[0] for col in cursor.description]
    return [dict(zip(columns, row)) for row in cursor.fetchall()]


def fetch_all(query, params=None):
    with connection.cursor() as cursor:
        cursor.execute(query, params or [])
        return rows_as_dicts(cursor)


def execute_returning(query, params=None):
    return fetch_all(query, params)


def quote_ident(value):
    return '"' + str(value).replace('"', '""') + '"'


def table_name(table):
    # PostgreSQL uses the dedicated ``curriculum`` schema; sqlite (tests) keeps
    # the tables in the default schema, so drop the schema qualifier there to
    # stay consistent with authoring_table_name().
    if connection.vendor != 'postgresql':
        return quote_ident(table)
    return f'{quote_ident(CURRICULUM_SCHEMA)}.{quote_ident(table)}'


def column_names(table):
    cache_key = f'{CURRICULUM_SCHEMA}.{table}'
    if cache_key in _TABLE_COLUMNS_CACHE:
        return _TABLE_COLUMNS_CACHE[cache_key]

    if connection.vendor == 'postgresql':
        rows = fetch_all(
            '''
            select column_name
            from information_schema.columns
            where table_schema = %s and table_name = %s
            ''',
            [CURRICULUM_SCHEMA, table],
        )
        names = {row['column_name'] for row in rows}
    else:
        with connection.cursor() as cursor:
            cursor.execute(f'pragma table_info({quote_ident(table)})')
            names = {row[1] for row in cursor.fetchall()}
    _TABLE_COLUMNS_CACHE[cache_key] = names
    return names


def has_column(table, column):
    return column in column_names(table)


def table_exists(table):
    # Cached because this runs on hot read paths and the schema does not change
    # under us; invalidate_curriculum_cache() clears it, as does a process restart.
    # A failed probe is deliberately not cached, so a transient error does not
    # pin a table to "missing" for the life of the process.
    cache_key = f'{CURRICULUM_SCHEMA}.{table}'
    if cache_key in _TABLE_EXISTS_CACHE:
        return _TABLE_EXISTS_CACHE[cache_key]
    try:
        if connection.vendor == 'postgresql':
            rows = fetch_all(
                '''
                select 1
                from information_schema.tables
                where table_schema = %s and table_name = %s
                limit 1
                ''',
                [CURRICULUM_SCHEMA, table],
            )
        else:
            rows = fetch_all(
                "select 1 from sqlite_master where type='table' and name = %s limit 1",
                [table],
            )
        exists = bool(rows)
        _TABLE_EXISTS_CACHE[cache_key] = exists
        return exists
    except (Exception, AssertionError):
        logger.debug('Could not check whether table %s exists.', table, exc_info=True)
        return False


def ensure_columns(table, specs):
    missing = {column: definition for column, definition in specs.items() if not has_column(table, column)}
    if not missing:
        return
    with connection.cursor() as cursor:
        for column, definition in missing.items():
            if connection.vendor == 'postgresql':
                add_column = f'add column if not exists {quote_ident(column)} {definition}'
            else:
                # SQLite supports ADD COLUMN but not ADD COLUMN IF NOT EXISTS.
                # ``missing`` was already calculated through PRAGMA table_info.
                add_column = f'add column {quote_ident(column)} {definition}'
            cursor.execute(
                f'alter table {table_name(table)} {add_column}'
            )
    _TABLE_COLUMNS_CACHE.pop(table, None)
    _TABLE_COLUMNS_CACHE.pop(f'{CURRICULUM_SCHEMA}.{table}', None)


