def ensure_live_sessions_table():
    global _LIVE_SESSIONS_TABLE_READY
    if _LIVE_SESSIONS_TABLE_READY:
        return
    if not schema_gate.runtime_bootstrap_allowed():
        schema_gate.require_tables(LIVE_SESSIONS_TABLE)
        _LIVE_SESSIONS_TABLE_READY = True
        return
    provision_live_sessions_table()


def provision_live_sessions_table():
    """Create/upgrade the live-sessions table. NOT for request paths."""
    global _LIVE_SESSIONS_TABLE_READY
    if _LIVE_SESSIONS_TABLE_READY:
        return
    json_type = 'jsonb' if connection.vendor == 'postgresql' else 'text'
    with connection.cursor() as cursor:
        if connection.vendor == 'postgresql':
            cursor.execute(f'create schema if not exists {quote_ident(CURRICULUM_SCHEMA)}')
        cursor.execute(f'''
            create table if not exists {authoring_table_name(LIVE_SESSIONS_TABLE)} (
                id varchar(128) primary key,
                module_catalogue_id varchar(128),
                module_draft_id varchar(255) not null default '',
                module_title varchar(500) not null default '',
                provider varchar(64) not null default 'Microsoft Teams',
                graph_event_id varchar(512),
                join_url text not null default '',
                web_link text not null default '',
                meeting_options_url text not null default '',
                organizer_email varchar(320) not null,
                attendees {json_type},
                presenters {json_type},
                start_datetime timestamp,
                timezone varchar(128) not null default '',
                duration_minutes integer not null default 60,
                repeat_pattern varchar(32) not null default 'none',
                repeat_occurrences integer not null default 1,
                lobby_bypass varchar(64) not null default 'invited',
                recording varchar(64) not null default 'none',
                spoken_language varchar(32) not null default 'en-GB',
                meeting_type varchar(64) not null default 'live-session',
                request_responses boolean not null default true,
                allow_time_proposals boolean not null default true,
                hide_attendees boolean not null default false,
                status varchar(32) not null default 'active',
                warnings {json_type},
                created_at timestamp not null default current_timestamp,
                updated_at timestamp not null default current_timestamp,
                foreign key (module_catalogue_id)
                    references {authoring_table_name(AUTHORING_MODULES_TABLE)} (module_catalogue_id)
                    on delete cascade
            )
        ''')
        cursor.execute(
            f'create index if not exists curriculum_live_sessions_module_idx '
            f'on {authoring_table_name(LIVE_SESSIONS_TABLE)} (module_catalogue_id)'
        )
        cursor.execute(
            f'create index if not exists curriculum_live_sessions_draft_idx '
            f'on {authoring_table_name(LIVE_SESSIONS_TABLE)} (module_draft_id)'
        )
        cursor.execute(
            f'create index if not exists curriculum_live_sessions_graph_event_idx '
            f'on {authoring_table_name(LIVE_SESSIONS_TABLE)} (graph_event_id)'
        )
    _TABLE_COLUMNS_CACHE.pop(f'{CURRICULUM_SCHEMA}.{LIVE_SESSIONS_TABLE}', None)
    _LIVE_SESSIONS_TABLE_READY = True


def ensure_live_session_tracking_tables():
    global _LIVE_SESSION_TRACKING_TABLES_READY
    if _LIVE_SESSION_TRACKING_TABLES_READY:
        return
    if not schema_gate.runtime_bootstrap_allowed():
        schema_gate.require_tables(
            LIVE_SESSIONS_TABLE,
            LIVE_SESSION_OCCURRENCES_TABLE,
            LIVE_SESSION_ATTENDANCE_TABLE,
            LIVE_SESSION_ARTIFACTS_TABLE,
            LIVE_SESSION_RECORDING_EVENTS_TABLE,
        )
        _LIVE_SESSION_TRACKING_TABLES_READY = True
        return
    provision_live_session_tracking_tables()


def provision_live_session_tracking_tables():
    """Create/upgrade live-session tracking schema. NOT for request paths."""
    global _LIVE_SESSION_TRACKING_TABLES_READY
    if _LIVE_SESSION_TRACKING_TABLES_READY:
        return
    ensure_live_sessions_table()
    live_sessions = authoring_table_name(LIVE_SESSIONS_TABLE)
    occurrences = authoring_table_name(LIVE_SESSION_OCCURRENCES_TABLE)
    attendance = authoring_table_name(LIVE_SESSION_ATTENDANCE_TABLE)
    artifacts = authoring_table_name(LIVE_SESSION_ARTIFACTS_TABLE)
    recording_events = authoring_table_name(LIVE_SESSION_RECORDING_EVENTS_TABLE)
    json_type = 'jsonb' if connection.vendor == 'postgresql' else 'text'
    with connection.cursor() as cursor:
        if connection.vendor == 'postgresql':
            cursor.execute(f"alter table {live_sessions} add column if not exists online_meeting_id text not null default ''")
            cursor.execute(f"alter table {live_sessions} add column if not exists presenters {json_type} not null default '[]'")
        elif 'online_meeting_id' not in column_names(LIVE_SESSIONS_TABLE):
            cursor.execute(f"alter table {live_sessions} add column online_meeting_id text not null default ''")
        if connection.vendor != 'postgresql' and 'presenters' not in column_names(LIVE_SESSIONS_TABLE):
            cursor.execute(f"alter table {live_sessions} add column presenters {json_type} not null default '[]'")
        cursor.execute(f'''
            create table if not exists {occurrences} (
                id varchar(128) primary key, live_session_id varchar(128) not null,
                session_number integer not null, graph_event_id varchar(512) not null default '',
                scheduled_start timestamp not null, scheduled_end timestamp not null,
                actual_start timestamp, actual_end timestamp, join_url text not null default '',
                online_meeting_id text not null default '',
                attendance_report_id varchar(512) not null default '', participant_count integer not null default 0,
                status varchar(32) not null default 'scheduled', artifacts_synced_at timestamp,
                last_sync_error text not null default '', created_at timestamp not null default current_timestamp,
                updated_at timestamp not null default current_timestamp,
                foreign key (live_session_id) references {live_sessions} (id) on delete cascade,
                unique (live_session_id, session_number)
            )
        ''')
        # A session the wizard had to move can end up on its own event with its
        # own online meeting, and Graph only answers for the meeting that ran.
        if connection.vendor == 'postgresql':
            cursor.execute(f"alter table {occurrences} add column if not exists online_meeting_id text not null default ''")
        elif 'online_meeting_id' not in column_names(LIVE_SESSION_OCCURRENCES_TABLE):
            cursor.execute(f"alter table {occurrences} add column online_meeting_id text not null default ''")
        cursor.execute(f'''
            create table if not exists {attendance} (
                id varchar(128) primary key, occurrence_id varchar(128) not null,
                graph_record_id varchar(512) not null default '', email varchar(320) not null default '',
                display_name varchar(500) not null default '', role varchar(64) not null default '',
                total_attendance_seconds integer not null default 0, intervals {json_type}, raw_data {json_type},
                created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp,
                foreign key (occurrence_id) references {occurrences} (id) on delete cascade
            )
        ''')
        cursor.execute(f'''
            create table if not exists {artifacts} (
                id varchar(128) primary key, occurrence_id varchar(128) not null,
                artifact_type varchar(32) not null, graph_artifact_id text not null,
                call_id text not null default '', content_correlation_id text not null default '',
                content_url text not null default '', created_datetime timestamp, end_datetime timestamp,
                metadata {json_type}, created_at timestamp not null default current_timestamp,
                updated_at timestamp not null default current_timestamp,
                foreign key (occurrence_id) references {occurrences} (id) on delete cascade,
                unique (occurrence_id, artifact_type, graph_artifact_id)
            )
        ''')
        cursor.execute(f'''
            create table if not exists {recording_events} (
                id varchar(128) primary key, live_session_id varchar(128) not null,
                occurrence_id varchar(128) not null default '', artifact_id varchar(128) not null,
                preview_session_id varchar(128) not null, event_type varchar(64) not null,
                viewer_id varchar(255) not null default '', viewer_email varchar(320) not null default '',
                viewer_name varchar(500) not null default '', viewer_role varchar(128) not null default '',
                browser_session_id varchar(128) not null default '', client_event_id varchar(128) not null default '',
                event_time timestamp not null default current_timestamp, video_time_seconds double precision not null default 0,
                previous_video_time_seconds double precision, duration_seconds double precision,
                watched_seconds_delta double precision not null default 0, playback_rate double precision not null default 1,
                volume double precision, muted boolean, skipped boolean not null default false,
                skip_from_seconds double precision, skip_to_seconds double precision, skip_delta_seconds double precision,
                viewport_width integer, viewport_height integer, user_agent text not null default '',
                page_url text not null default '', referrer text not null default '', metadata {json_type},
                created_at timestamp not null default current_timestamp,
                foreign key (live_session_id) references {live_sessions} (id) on delete cascade,
                foreign key (artifact_id) references {artifacts} (id) on delete cascade
            )
        ''')
        cursor.execute(f'create index if not exists curriculum_live_occurrence_series_idx on {occurrences} (live_session_id)')
        cursor.execute(f'create index if not exists curriculum_live_occurrence_start_idx on {occurrences} (scheduled_start)')
        cursor.execute(f'create index if not exists curriculum_live_attendance_occurrence_idx on {attendance} (occurrence_id)')
        cursor.execute(f'create index if not exists curriculum_live_artifact_occurrence_idx on {artifacts} (occurrence_id)')
        cursor.execute(f'create index if not exists curriculum_recording_events_artifact_idx on {recording_events} (artifact_id)')
        cursor.execute(f'create index if not exists curriculum_recording_events_preview_idx on {recording_events} (preview_session_id)')
        cursor.execute(f'create index if not exists curriculum_recording_events_viewer_idx on {recording_events} (viewer_email, viewer_id)')
        cursor.execute(f'create index if not exists curriculum_recording_events_time_idx on {recording_events} (event_time)')
    for table in (LIVE_SESSIONS_TABLE, LIVE_SESSION_OCCURRENCES_TABLE, LIVE_SESSION_ATTENDANCE_TABLE, LIVE_SESSION_ARTIFACTS_TABLE, LIVE_SESSION_RECORDING_EVENTS_TABLE):
        _TABLE_COLUMNS_CACHE.pop(f'{CURRICULUM_SCHEMA}.{table}', None)
    _LIVE_SESSION_TRACKING_TABLES_READY = True


def parse_graph_datetime(value):
    raw = clean_str(value)
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace('Z', '+00:00'))
    except ValueError:
        return None


def utc_iso_value(value):
    """A stored live-session timestamp as an instant that names its offset.

    The occurrence tables are `timestamp without time zone` holding UTC, so a
    plain `isoformat()` hands the browser `2026-12-12T09:00:00` -- which
    JavaScript reads as the *reader's own* local time. A viewer in Cairo then
    sees every meeting two hours early and every date reads as out of sync,
    while the identical data looks right in London. Stamping the offset leaves
    nothing to guess: the reader's calendar renders the instant in whatever zone
    that reader is in, exactly as Teams itself does.
    """
    if isinstance(value, datetime):
        stamped = value if value.tzinfo is not None else value.replace(tzinfo=timezone.utc)
        return stamped.astimezone(timezone.utc).isoformat()
    return clean_str(value)


# The live-session tables that hold a UTC instant rather than a wall clock. Every
# one of them reaches a browser, so every one of them has to carry its offset.
LIVE_SESSION_INSTANT_FIELDS = (
    'scheduled_start', 'scheduled_end', 'actual_start', 'actual_end',
    'artifacts_synced_at', 'created_at', 'updated_at', 'start_datetime',
)


def stamp_live_session_instants(row):
    """Return `row` with its UTC timestamp columns carrying an explicit offset."""
    if not isinstance(row, dict):
        return row
    for field in LIVE_SESSION_INSTANT_FIELDS:
        if isinstance(row.get(field), datetime):
            row[field] = utc_iso_value(row[field])
    return row


def scheduled_live_session_occurrences(payload, utc_start, duration, repeat, occurrences):
    supplied = payload.get('scheduledOccurrences')
    normalized = []
    if isinstance(supplied, list):
        for index, item in enumerate(supplied):
            if not isinstance(item, dict):
                continue
            start = parse_graph_datetime(item.get('startDateTimeUtc'))
            if not start:
                continue
            item_duration = max(15, min(1440, int(item.get('durationMinutes') or duration)))
            normalized.append({
                'session_number': max(1, int(item.get('sessionNumber') or index + 1)),
                'start': start,
                'end': start + timedelta(minutes=item_duration),
            })
    if normalized:
        return sorted(normalized, key=lambda item: (item['session_number'], item['start']))
    count = occurrences if repeat != 'none' else 1
    current = utc_start
    for index in range(count):
        normalized.append({'session_number': index + 1, 'start': current, 'end': current + timedelta(minutes=duration)})
        if repeat == 'daily':
            current += timedelta(days=1)
        elif repeat == 'weekdays':
            current += timedelta(days=1)
            while current.weekday() >= 5:
                current += timedelta(days=1)
        else:
            current += timedelta(days=7)
    return normalized


def persist_live_session_occurrences(live_session_id, payload, event, utc_start, duration, repeat, occurrences):
    ensure_live_session_tracking_tables()
    now = datetime.utcnow()
    join_url = clean_str((event.get('onlineMeeting') or {}).get('joinUrl'))
    rows = scheduled_live_session_occurrences(payload, utc_start, duration, repeat, occurrences)
    for item in rows:
        authoring_upsert(LIVE_SESSION_OCCURRENCES_TABLE, ['live_session_id', 'session_number'], {
            'id': f'OCC-{uuid.uuid4().hex.upper()}',
            'live_session_id': live_session_id,
            'session_number': item['session_number'],
            'graph_event_id': clean_str(event.get('id')),
            'scheduled_start': item['start'],
            'scheduled_end': item['end'],
            'join_url': join_url,
            'status': 'scheduled',
            'created_at': now,
            'updated_at': now,
        })
    return rows


def replace_live_session_occurrences(live_session_id, payload, utc_start, duration, repeat, occurrences, event_id='', join_url=''):
    ensure_live_session_tracking_tables()
    now = datetime.utcnow()
    rows = scheduled_live_session_occurrences(payload, utc_start, duration, repeat, occurrences)
    existing_rows = authoring_fetch_all(LIVE_SESSION_OCCURRENCES_TABLE, 'live_session_id = %s', [live_session_id])
    def occurrence_number(row):
        try:
            return int((row or {}).get('session_number') or 0)
        except (TypeError, ValueError):
            return 0
    existing_by_number = {
        occurrence_number(row): row
        for row in existing_rows
        if occurrence_number(row) > 0
    }
    active_numbers = set()
    for item in rows:
        session_number = item['session_number']
        active_numbers.add(session_number)
        existing = existing_by_number.get(session_number) or {}
        authoring_upsert(LIVE_SESSION_OCCURRENCES_TABLE, ['live_session_id', 'session_number'], {
            'id': clean_str(existing.get('id')) or f'OCC-{uuid.uuid4().hex.upper()}',
            'live_session_id': live_session_id,
            'session_number': session_number,
            'graph_event_id': clean_str(event_id),
            'scheduled_start': item['start'],
            'scheduled_end': item['end'],
            'join_url': clean_str(join_url),
            'status': 'scheduled',
            'created_at': existing.get('created_at') or now,
            'updated_at': now,
        })
    if active_numbers:
        stale_ids = [clean_str(row.get('id')) for row in existing_rows if occurrence_number(row) not in active_numbers]
        if stale_ids:
            placeholders = ', '.join(['%s'] * len(stale_ids))
            update_authoring_rows(
                LIVE_SESSION_OCCURRENCES_TABLE,
                f"id in ({placeholders})",
                stale_ids,
                {'status': 'cancelled', 'updated_at': now},
            )
    return rows


def persist_live_session_series(payload, event, warnings, graph_settings, organizer, attendees, presenters, online_meeting_id=''):
    ensure_module_authoring_tables()
    ensure_live_session_tracking_tables()
    module_catalogue_id = clean_str(payload.get('moduleCatalogueId'))
    if module_catalogue_id and not authoring_module_exists(module_catalogue_id):
        module_catalogue_id = ''
    module_draft_id = clean_str(payload.get('moduleDraftId'))
    now = datetime.utcnow()
    supersede_filters = []
    supersede_params = []
    if module_catalogue_id:
        supersede_filters.append('module_catalogue_id = %s')
        supersede_params.append(module_catalogue_id)
    elif module_draft_id:
        supersede_filters.append('module_draft_id = %s')
        supersede_params.append(module_draft_id)
    if supersede_filters:
        update_authoring_rows(
            LIVE_SESSIONS_TABLE,
            f"status = 'active' and ({' or '.join(supersede_filters)})",
            supersede_params,
            {'status': 'superseded', 'updated_at': now},
        )

    live_session_id = f'LIVE-{uuid.uuid4().hex.upper()}'
    start_datetime = None
    start_raw = clean_str(payload.get('startDateTimeUtc'))
    if start_raw:
        try:
            start_datetime = datetime.fromisoformat(start_raw.replace('Z', '+00:00'))
        except ValueError:
            start_datetime = None
    authoring_upsert(LIVE_SESSIONS_TABLE, ['id'], {
        'id': live_session_id,
        'module_catalogue_id': module_catalogue_id or None,
        'module_draft_id': module_draft_id,
        'module_title': clean_str(payload.get('moduleTitle') or payload.get('title')),
        'provider': 'Microsoft Teams',
        'graph_event_id': clean_str(event.get('id')) or None,
        'online_meeting_id': online_meeting_id,
        'join_url': clean_str((event.get('onlineMeeting') or {}).get('joinUrl')),
        'web_link': clean_str(event.get('webLink')),
        'meeting_options_url': clean_str(event.get('_meetingOptionsUrl')),
        'organizer_email': organizer,
        'attendees': json_db_value(attendees),
        'presenters': json_db_value(presenters),
        'start_datetime': start_datetime,
        'timezone': graph_settings.get('timezone') or '',
        'duration_minutes': max(15, min(1440, int(payload.get('durationMinutes') or 60))),
        'repeat_pattern': clean_str(payload.get('repeat')).lower() or 'none',
        'repeat_occurrences': max(1, min(52, int(payload.get('repeatOccurrences') or 1))),
        'lobby_bypass': clean_str(payload.get('lobbyBypass')).lower() or 'invited',
        'recording': clean_str(payload.get('recording')).lower() or 'none',
        'spoken_language': clean_str(payload.get('spokenLanguage')) or 'en-GB',
        'meeting_type': clean_str(payload.get('meetingType')) or 'live-session',
        'request_responses': bool(payload.get('requestResponses', True)),
        'allow_time_proposals': bool(payload.get('allowNewTimeProposals', True)),
        'hide_attendees': bool(payload.get('hideAttendees', False)),
        'status': 'active',
        'warnings': json_db_value(warnings),
        'created_at': now,
        'updated_at': now,
    })
    occurrence_rows = persist_live_session_occurrences(
        live_session_id,
        payload,
        event,
        parse_graph_datetime(payload.get('startDateTimeUtc')) or now,
        max(15, min(1440, int(payload.get('durationMinutes') or 60))),
        clean_str(payload.get('repeat')).lower() or 'none',
        max(1, min(52, int(payload.get('repeatOccurrences') or 1))),
    )
    return live_session_id, len(occurrence_rows)


def link_live_session_series_to_module(module_catalogue_id, payload):
    ensure_live_sessions_table()
    live_session_ids = set()
    for week in payload.get('weekStructure') or []:
        for component in week.get('components') or []:
            settings_payload = component.get('settings') if isinstance(component.get('settings'), dict) else {}
            live_session_id = clean_str(settings_payload.get('teamsLiveSessionId'))
            if live_session_id:
                live_session_ids.add(live_session_id)
    delivery_metadata = payload.get('deliveryMetadata') if isinstance(payload.get('deliveryMetadata'), dict) else {}
    metadata_id = clean_str(delivery_metadata.get('teamsLiveSessionId'))
    if metadata_id:
        live_session_ids.add(metadata_id)
    for live_session_id in live_session_ids:
        update_authoring_rows(
            LIVE_SESSIONS_TABLE,
            'id = %s',
            [live_session_id],
            {'module_catalogue_id': module_catalogue_id, 'updated_at': datetime.utcnow()},
        )


def teams_meeting_default_organizer():
    # Client credentials identify the application, not the licensed Microsoft
    # 365 user whose calendar owns the event. Keep that UPN configurable.
    return clean_str(
        os.environ.get('MICROSOFT_TEAMS_ORGANIZER_EMAIL')
        or os.environ.get('MICROSOFT_ORGANIZER_EMAIL')
    )


def teams_new_meeting_organizer(requested=''):
    """The mailbox a *new* Teams meeting is created on.

    A configured organizer deliberately outranks whatever the caller asked for.
    Recording, transcription and the lobby are not set on the calendar event --
    they are set on the onlineMeeting behind it, and that route is gated by a
    Teams application access policy granted *per user*. A meeting created on any
    other mailbox is refused with `403 forbidden: No application access policy
    found for this app ... on the user`, and opens at the tenant defaults:
    nothing records, and there is no transcript afterwards.

    Tutors belong on the meeting as presenters, which is what `presenters` is
    for. They do not have to own it. Only when nothing is configured does the
    caller's own value stand, which is what keeps a deployment that has not set
    the organizer working exactly as it did before.
    """
    configured = teams_meeting_default_organizer()
    return configured or clean_str(requested)


def teams_attendee_emails(value):
    if isinstance(value, list):
        candidates = value
    else:
        candidates = re.split(r'[\s,;]+', clean_str(value))
    emails = []
    seen = set()
    for item in candidates:
        email = clean_str(item).lower()
        if not email or email in seen:
            continue
        if not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email):
            raise ValueError(f'Invalid attendee email: {email}')
        seen.add(email)
        emails.append(email)
    return emails


def teams_event_recurrence(repeat, local_start, occurrences):
    if repeat == 'none':
        return None
    start_date = local_start.date().isoformat()
    day_name = local_start.strftime('%A').lower()
    if repeat == 'daily':
        pattern = {'type': 'daily', 'interval': 1}
    elif repeat == 'weekdays':
        pattern = {
            'type': 'weekly',
            'interval': 1,
            'daysOfWeek': ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'],
        }
    else:
        pattern = {'type': 'weekly', 'interval': 1, 'daysOfWeek': [day_name]}
    return {
        'pattern': pattern,
        'range': {
            'type': 'numbered',
            'startDate': start_date,
            'numberOfOccurrences': occurrences,
        },
    }


def teams_recurrence_slot_count(payload, local_start, repeat, occurrences):
    """Weekly slots the recurrence must span to reach the last shifted session.

    A holiday-shifted plan keeps the session count but stretches the calendar span,
    so a series numbered by session count ends before the final shifted date and
    Graph never materialises an instance for it. Count slots from the first to the
    last supplied occurrence instead, keeping the session count as the floor.
    """
    if repeat == 'none':
        return occurrences
    supplied = payload.get('scheduledOccurrences')
    if not isinstance(supplied, list):
        return occurrences
    starts = []
    for item in supplied:
        if not isinstance(item, dict):
            continue
        parsed = parse_graph_datetime(item.get('startDateTimeUtc'))
        if parsed:
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
            starts.append(parsed)
    if len(starts) < 2:
        return occurrences
    span_days = (max(starts).date() - min(starts).date()).days
    if span_days <= 0:
        return occurrences
    step = 1 if repeat in ('daily', 'weekdays') else 7
    spanned = span_days // step + 1
    return max(occurrences, min(52, spanned))


def teams_event_body_html(title, details=''):
    """Branded HTML body for a Module Builder Teams calendar invite.

    Calendar clients sanitize event descriptions inconsistently (Outlook keeps
    inline styles, Google Calendar's forwarded-mail rendering is pickier), so
    this leans on a small set of inline styles that degrade gracefully to
    plain, still-readable text if a client strips them.
    """
    parts = [
        '<p style="margin:0 0 6px;font-size:11px;font-weight:600;letter-spacing:0.4px;'
        'color:#616e7c;text-transform:uppercase;">KBC LearningOS &middot; Module Builder</p>',
        f'<p style="margin:0 0 16px;font-size:18px;font-weight:600;color:#0b3d6b;">{escape(title)}</p>',
    ]
    if details:
        parts.append(
            '<p style="margin:0 0 16px;font-size:14px;line-height:1.55;color:#1f2933;">'
            f'{escape(details).replace(chr(10), "<br>")}</p>'
        )
    parts.append('<hr style="border:none;border-top:1px solid #e4e7eb;margin:0;">')
    return ''.join(parts)


def teams_event_payload(payload, graph_settings):
    title = clean_str(payload.get('title')) or 'Live session'
    local_start_raw = clean_str(payload.get('localStartDateTime'))
    utc_start_raw = clean_str(payload.get('startDateTimeUtc'))
    try:
        local_start = datetime.fromisoformat(local_start_raw)
    except ValueError as exc:
        raise ValueError('A valid meeting start date and time is required.') from exc
    try:
        utc_start = datetime.fromisoformat(utc_start_raw.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValueError('A valid UTC meeting start date and time is required.') from exc

    duration = max(15, min(1440, int(payload.get('durationMinutes') or 60)))
    repeat = clean_str(payload.get('repeat')).lower() or 'none'
    if repeat not in TEAMS_REPEAT_VALUES:
        raise ValueError('Unsupported repeat option.')
    occurrences = max(2, min(52, int(payload.get('repeatOccurrences') or 12)))
    attendees = teams_attendee_emails(payload.get('attendees'))
    presenters = teams_attendee_emails(payload.get('presenters'))
    invited_people = list(dict.fromkeys([*presenters, *attendees]))
    details = clean_str(payload.get('details'))

    # Anchor the series to the same UTC instant the per-session occurrences are
    # derived from. The wizard computes those in the browser's timezone, so reading
    # the naive local string in the organizer's Graph timezone can put the weekly
    # grid hours away from every target: nothing matches, every occurrence has to be
    # moved, and Graph rejects moves that cross a neighbour -- which shreds the
    # series into standalone recreations. Same instant either way, minus the churn.
    anchor = utc_start
    if anchor.tzinfo is not None:
        anchor = anchor.astimezone(timezone.utc).replace(tzinfo=None)
    anchor = anchor.replace(second=0, microsecond=0)
    event = {
        'subject': title,
        'body': {'contentType': 'HTML', 'content': teams_event_body_html(title, details)},
        'start': {
            'dateTime': anchor.isoformat(timespec='seconds'),
            'timeZone': 'UTC',
        },
        'end': {
            'dateTime': (anchor + timedelta(minutes=duration)).isoformat(timespec='seconds'),
            'timeZone': 'UTC',
        },
        'attendees': [
            {'emailAddress': {'address': email, 'name': email.split('@', 1)[0]}, 'type': 'required'}
            for email in invited_people
        ],
        'isOnlineMeeting': True,
        'onlineMeetingProvider': 'teamsForBusiness',
        'responseRequested': bool(payload.get('requestResponses', True)),
        'allowNewTimeProposals': bool(payload.get('allowNewTimeProposals', True)),
        'hideAttendees': bool(payload.get('hideAttendees', False)),
    }
    transaction_id = clean_str(payload.get('transactionId'))[:255]
    if transaction_id:
        event['transactionId'] = transaction_id
    # Holiday shifts stretch the calendar span past the Nth weekly slot, so size the
    # recurrence by the span the wizard actually needs. Sizing it by session count
    # leaves the trailing shifted dates with no instance to move onto.
    recurrence_slots = teams_recurrence_slot_count(payload, anchor, repeat, occurrences)
    recurrence = teams_event_recurrence(repeat, anchor, max(2, recurrence_slots))
    if recurrence:
        event['recurrence'] = recurrence
    # Return normalized timing too, for the component settings response.
    return event, invited_people, presenters, utc_start, duration, repeat, occurrences


def teams_single_occurrence_payload(title, target, attendees):
    return {
        'subject': title,
        'body': {'contentType': 'HTML', 'content': teams_event_body_html(title)},
        'start': {
            'dateTime': target['start'].replace(second=0, microsecond=0).isoformat(timespec='seconds'),
            'timeZone': 'UTC',
        },
        'end': {
            'dateTime': target['end'].replace(second=0, microsecond=0).isoformat(timespec='seconds'),
            'timeZone': 'UTC',
        },
        'attendees': [
            {'emailAddress': {'address': email, 'name': email.split('@', 1)[0]}, 'type': 'required'}
            for email in attendees
        ],
        'isOnlineMeeting': True,
        'onlineMeetingProvider': 'teamsForBusiness',
        'responseRequested': True,
        'allowNewTimeProposals': True,
        'hideAttendees': False,
    }


def teams_calendar_minute_key(value):
    parsed = value if isinstance(value, datetime) else parse_graph_datetime(value)
    if not parsed:
        return ''
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    return parsed.replace(second=0, microsecond=0).isoformat(timespec='minutes')


def teams_series_email_list(*values):
    emails = []
    for value in values:
        if isinstance(value, str):
            candidates = parse_json_value(value, [])
            if not isinstance(candidates, list):
                candidates = re.split(r'[\s,;]+', value)
        elif isinstance(value, (list, tuple, set)):
            candidates = value
        else:
            candidates = []
        for candidate in candidates:
            email = clean_str(candidate).lower()
            if email and email not in emails:
                emails.append(email)
    return emails


def teams_online_meeting_owner_id(organizer, join_url=''):
    """Return the organizer object ID required by onlineMeetings Graph routes."""
    configured_id = clean_str(os.environ.get('MICROSOFT_TEAMS_ORGANIZER_ID'))
    if re.fullmatch(r'[0-9a-fA-F-]{36}', configured_id):
        return configured_id
    try:
        decoded_url = urllib_parse.unquote(clean_str(join_url))
        context_values = urllib_parse.parse_qs(urlparse(decoded_url).query).get('context') or []
        if context_values:
            context = json.loads(urllib_parse.unquote(context_values[0]))
            organizer_id = clean_str(context.get('Oid') or context.get('oid'))
            if re.fullmatch(r'[0-9a-fA-F-]{36}', organizer_id):
                return organizer_id
    except (TypeError, ValueError, json.JSONDecodeError):
        pass
    return clean_str(organizer)


def teams_online_meeting_from_join_url(organizer, join_url):
    """Find the onlineMeeting behind a calendar event when permissions allow."""
    if not join_url:
        return {}
    escaped_url = join_url.replace("'", "''")
    query = urllib_parse.urlencode({'$filter': f"joinWebUrl eq '{escaped_url}'"})
    owner_key = urllib_parse.quote(teams_online_meeting_owner_id(organizer, join_url), safe='')
    from coach_api.views import microsoft_graph_request
    response = microsoft_graph_request('GET', f'users/{owner_key}/onlineMeetings?{query}')
    values = response.get('value') if isinstance(response, dict) else []
    return values[0] if values else {}


# Graph names timezones the Windows way; browsers only know IANA ids. Only the zones
# this deployment can realistically be configured with need an entry -- anything else
# is covered by the MICROSOFT_GRAPH_TIMEZONE_IANA override.
GRAPH_WINDOWS_TO_IANA = {
    'GMT Standard Time': 'Europe/London',
    'UTC': 'UTC',
    'W. Europe Standard Time': 'Europe/Berlin',
    'Romance Standard Time': 'Europe/Paris',
    'Egypt Standard Time': 'Africa/Cairo',
    'Arabian Standard Time': 'Asia/Dubai',
}


def graph_timezone_iana(graph_settings):
    """IANA id for the calendar's timezone, for the wizard to schedule against."""
    override = clean_str(os.environ.get('MICROSOFT_GRAPH_TIMEZONE_IANA'))
    if override:
        return override
    return GRAPH_WINDOWS_TO_IANA.get(clean_str(graph_settings.get('timezone')), 'Europe/London')


def teams_shifted_occurrence_targets(payload, default_duration):
    """Wizard dates the calendar occurrences must land on, holiday shifts included."""
    supplied = payload.get('scheduledOccurrences')
    if not isinstance(supplied, list) or len(supplied) <= 1:
        return []
    targets = []
    for index, item in enumerate(supplied):
        if not isinstance(item, dict):
            continue
        start = parse_graph_datetime(item.get('startDateTimeUtc'))
        if not start:
            continue
        try:
            item_duration = max(15, min(1440, int(item.get('durationMinutes') or default_duration)))
        except (TypeError, ValueError):
            item_duration = default_duration
        try:
            session_number = max(1, int(item.get('sessionNumber') or index + 1))
        except (TypeError, ValueError):
            session_number = index + 1
        targets.append({
            'session_number': session_number,
            'start': start,
            'end': start + timedelta(minutes=item_duration),
        })
    return targets


def apply_teams_occurrence_shifts(
    owner_key,
    event_key,
    title,
    target_occurrences,
    invited_people,
    meeting_options=None,
):
    """Move the plain weekly Graph occurrences onto the wizard's shifted dates.

    Graph recurrences can only be unbroken weekly patterns, so a holiday-shifted plan
    has to be reconciled instance by instance once the series exists. Creating a
    series needs this exactly as much as rescheduling one does: the wizard sends the
    shifted dates on both calls, and skipping the reconciliation leaves Teams showing
    sessions on the very holidays the wizard moved them off.

    Returns `(warnings, recreated)`. An empty warning list means the calendar
    matches the plan; `recreated` describes every session Graph would only accept
    as an event of its own, so the caller can record the event, Teams link and
    online meeting that session now really has.
    """
    from coach_api.views import microsoft_graph_request

    warnings = []
    recreated_details = []
    if not target_occurrences:
        return warnings, recreated_details

    instance_start = (min(item['start'] for item in target_occurrences) - timedelta(days=7)).isoformat()
    instance_end = (max(item['end'] for item in target_occurrences) + timedelta(days=7)).isoformat()
    # Graph pages /instances at 10 by default. Without an explicit $top the later
    # sessions of a long series are simply invisible here, so their holiday shifts
    # were never applied and the pairing below mistook present-but-unlisted slots
    # for missing ones. Series length is capped at 52 occurrences, so one page fits.
    instance_query = urllib_parse.urlencode({
        'startDateTime': instance_start,
        'endDateTime': instance_end,
        '$top': 200,
    })
    target_by_key = {
        teams_calendar_minute_key(target['start']): target
        for target in target_occurrences
    }
    try:
        instance_response = microsoft_graph_request('GET', f'users/{owner_key}/events/{event_key}/instances?{instance_query}')
        instances = instance_response.get('value') if isinstance(instance_response, dict) else []
        instances = sorted(instances, key=lambda item: clean_str((item.get('start') or {}).get('dateTime')))
        recreated_event_ids = set()
        # Claim instances that already sit on a wanted date before assigning the
        # rest. Pairing purely by position would move an instance that is already
        # correct onto another wanted date and duplicate it, because a shifted
        # series spans more weekly slots than there are sessions.
        sorted_targets = sorted(target_occurrences, key=lambda item: item['session_number'])
        remaining_instances = list(instances)
        paired_instances = []
        unmatched_targets = []
        for target in sorted_targets:
            target_key = teams_calendar_minute_key(target['start'])
            match = next(
                (
                    candidate for candidate in remaining_instances
                    if teams_calendar_minute_key((candidate.get('start') or {}).get('dateTime')) == target_key
                ),
                None,
            )
            if match is None:
                unmatched_targets.append(target)
                continue
            remaining_instances.remove(match)
            paired_instances.append((match, target))
        # A target already on the right day but at a different clock time -- a DST
        # boundary moves the UTC instant by an hour -- belongs to that day's
        # instance. Only genuinely date-shifted sessions fall through to position,
        # where a wrong guess drags an occurrence across its neighbour.
        positional_targets = []
        for target in unmatched_targets:
            target_day = target['start'].date()
            match = next(
                (
                    candidate for candidate in remaining_instances
                    if (parse_graph_datetime((candidate.get('start') or {}).get('dateTime')) or datetime.min).date() == target_day
                ),
                None,
            )
            if match is None:
                positional_targets.append(target)
                continue
            remaining_instances.remove(match)
            paired_instances.append((match, target))
        for target in positional_targets:
            if not remaining_instances:
                break
            paired_instances.append((remaining_instances.pop(0), target))
        for instance, target in reversed(paired_instances):
            instance_id = clean_str(instance.get('id'))
            if not instance_id:
                continue
            current_key = teams_calendar_minute_key((instance.get('start') or {}).get('dateTime'))
            target_key = teams_calendar_minute_key(target['start'])
            if current_key and current_key == target_key:
                continue
            instance_key = urllib_parse.quote(instance_id, safe='')
            try:
                microsoft_graph_request('PATCH', f'users/{owner_key}/events/{instance_key}', payload={
                    'start': {'dateTime': target['start'].replace(second=0, microsecond=0).isoformat(timespec='seconds'), 'timeZone': 'UTC'},
                    'end': {'dateTime': target['end'].replace(second=0, microsecond=0).isoformat(timespec='seconds'), 'timeZone': 'UTC'},
                })
            except RuntimeError as exc:
                recreated = microsoft_graph_request(
                    'POST',
                    f'users/{owner_key}/events',
                    payload=teams_single_occurrence_payload(title, target, invited_people),
                )
                if isinstance(recreated, dict):
                    recreated_id = clean_str(recreated.get('id'))
                    if recreated_id:
                        recreated_event_ids.add(recreated_id)
                    # The new event brought a new onlineMeeting with it, at the
                    # tenant defaults. Without this the moved session is the one
                    # that opens with nothing recording and no transcript after it.
                    standalone = teams_standalone_occurrence_meeting(
                        owner_key, recreated, target, invited_people, meeting_options,
                    )
                    warnings.extend(standalone.pop('warnings'))
                    recreated_details.append(standalone)
                microsoft_graph_request('DELETE', f'users/{owner_key}/events/{instance_key}')
                warnings.append({
                    'code': 'teams_shifted_occurrence_recreated',
                    'message': 'Microsoft Teams could not move a recurring occurrence across the series boundary, so it was recreated on the wizard date and the old occurrence was removed.',
                    'detail': str(exc),
                })
        instance_response = microsoft_graph_request('GET', f'users/{owner_key}/events/{event_key}/instances?{instance_query}')
        instances = instance_response.get('value') if isinstance(instance_response, dict) else []
        for instance in instances:
            instance_id = clean_str(instance.get('id'))
            if not instance_id or instance_id in recreated_event_ids:
                continue
            current_key = teams_calendar_minute_key((instance.get('start') or {}).get('dateTime'))
            if current_key and current_key not in target_by_key:
                microsoft_graph_request('DELETE', f'users/{owner_key}/events/{urllib_parse.quote(instance_id, safe="")}')
    except RuntimeError as exc:
        logger.warning('Unable to reconcile individual Teams event instances: %s', exc)
        warnings.append({
            'code': 'teams_individual_occurrences_not_updated',
            'message': 'Microsoft Teams updated the meeting series, but could not update shifted individual sessions.',
            'detail': str(exc),
        })
    return warnings, recreated_details


def teams_meeting_base_path(organizer, meeting_id, join_url=''):
    """Graph path of one onlineMeeting, resolved for the organizer that owns it."""
    owner_key = urllib_parse.quote(teams_online_meeting_owner_id(organizer, join_url), safe='')
    return f'users/{owner_key}/onlineMeetings/{urllib_parse.quote(clean_str(meeting_id), safe="")}'


def apply_teams_meeting_options(
    organizer,
    join_url,
    recording='none',
    lobby_bypass='invited',
    spoken_language='en-GB',
    attendees=(),
    presenters=(),
    online_meeting_id='',
    meeting=None,
):
    """Apply this deployment's meeting policy to the onlineMeeting behind an event.

    Every Teams meeting the LMS owns comes through here: a module's series, a
    rescheduled one, a holiday-shifted session recreated on its own event, and a
    coach's booking alike. A calendar event only ever creates the meeting at the
    tenant defaults, so recording, automatic recording, transcription, the lobby
    and who presents exist only once this has run against it -- a meeting that
    skips it opens with nothing recording, no transcript afterwards, and every
    guest a presenter.

    Returns ``(applied, meeting, warnings)`` and never raises. The calendar
    invitation is real work already done, and these options need
    OnlineMeetings.ReadWrite.All plus an application access policy on the
    organizer that a deployment may not have granted yet.
    """
    from coach_api.views import microsoft_graph_request

    resolved = meeting if isinstance(meeting, dict) else {}
    meeting_id = clean_str(online_meeting_id) or clean_str(resolved.get('id'))
    if not meeting_id and join_url:
        try:
            resolved = teams_online_meeting_from_join_url(organizer, join_url) or {}
        except RuntimeError as exc:
            logger.warning('Unable to resolve the onlineMeeting behind a Teams event: %s', exc)
            return False, resolved, [{
                'code': 'teams_meeting_options_not_applied',
                'message': (
                    'The Teams link was created, but its online meeting could not be resolved, so the recording, '
                    'transcription and lobby options were not applied. Grant OnlineMeetings.ReadWrite.All and an '
                    'application access policy to the organizer.'
                ),
                'detail': str(exc),
            }]
        meeting_id = clean_str(resolved.get('id'))
    if not meeting_id:
        return False, resolved, [{
            'code': 'teams_meeting_options_not_applied',
            'message': (
                'Microsoft Graph has not exposed this meeting: its online meeting ID is not available yet, so the '
                'recording, transcription and lobby options were not applied.'
            ),
            'detail': '',
        }]

    lobby_choice = clean_str(lobby_bypass).lower() or 'invited'
    if lobby_choice not in TEAMS_LOBBY_VALUES:
        lobby_choice = 'invited'
    recording_choice = clean_str(recording).lower() or 'none'
    presenter_emails = teams_series_email_list(list(presenters))
    roster = teams_series_email_list(presenter_emails, list(attendees))
    patch = {
        'lobbyBypassSettings': {
            'scope': TEAMS_LOBBY_VALUES[lobby_choice],
            'isDialInBypassEnabled': False,
        },
        'allowRecording': recording_choice != 'none',
        'recordAutomatically': recording_choice != 'none',
        'allowTranscription': recording_choice == 'record-transcribe',
        'meetingSpokenLanguageTag': clean_str(spoken_language) or 'en-GB',
    }
    # The roster goes on the meeting whether or not anyone presents: it is what
    # tells Teams these people belong to this meeting rather than being guests who
    # found the link. `allowedPresenters` stays at the tenant default until a
    # presenter is actually named, because naming nobody would mute the tutor too.
    if roster:
        presenter_set = set(presenter_emails)
        patch['participants'] = {
            'attendees': [
                {'upn': email, 'role': 'presenter' if email in presenter_set else 'attendee'}
                for email in roster
            ],
        }
    if presenter_emails:
        patch['allowedPresenters'] = 'roleIsPresenter'
    try:
        microsoft_graph_request(
            'PATCH',
            teams_meeting_base_path(organizer, meeting_id, join_url),
            payload=patch,
        )
    except RuntimeError as exc:
        logger.warning('Unable to apply Teams meeting options: %s', exc)
        return False, resolved, [{
            'code': 'teams_meeting_options_not_applied',
            'message': (
                'The Teams meeting exists, but its lobby, recording, transcription and presenter options were not '
                'applied. Grant OnlineMeetings.ReadWrite.All and an application access policy to the organizer.'
            ),
            'detail': str(exc),
        }]
    return True, resolved, []


def teams_standalone_occurrence_meeting(owner_key, event, target, invited_people, meeting_options):
    """Give an occurrence recreated on its own event the options its series has.

    Graph builds a fresh onlineMeeting for a fresh event, at the tenant defaults,
    and the series own options never reach it. Left alone, the one session that
    had to move is the one that records nothing and produces no transcript.
    """
    from coach_api.views import microsoft_graph_request

    warnings = []
    event_id = clean_str((event or {}).get('id'))
    join_url = clean_str(((event or {}).get('onlineMeeting') or {}).get('joinUrl'))
    if event_id and not join_url:
        try:
            refreshed = microsoft_graph_request(
                'GET',
                f'users/{owner_key}/events/{urllib_parse.quote(event_id, safe="")}',
            )
            join_url = clean_str(((refreshed or {}).get('onlineMeeting') or {}).get('joinUrl'))
        except RuntimeError as exc:
            logger.warning('Unable to read the Teams link of a recreated occurrence: %s', exc)
    options = meeting_options or {}
    online_meeting_id = ''
    if join_url and options:
        _applied, meeting, option_warnings = apply_teams_meeting_options(
            options.get('organizer', ''),
            join_url,
            recording=options.get('recording', 'none'),
            lobby_bypass=options.get('lobby_bypass', 'invited'),
            spoken_language=options.get('spoken_language', 'en-GB'),
            attendees=invited_people,
            presenters=options.get('presenters') or [],
        )
        warnings.extend(option_warnings)
        online_meeting_id = clean_str((meeting or {}).get('id'))
    return {
        'session_number': (target or {}).get('session_number'),
        'graph_event_id': event_id,
        'join_url': join_url,
        'online_meeting_id': online_meeting_id,
        'warnings': warnings,
    }


def persist_recreated_occurrence_details(live_session_id, recreated_details):
    """Point a moved session at the event and meeting Teams actually gave it.

    A recreated occurrence is its own event with its own Teams link and its own
    online meeting, so the series link and meeting ID are the wrong answer for
    it: learners would join a session that no longer exists, and its transcript,
    recording and attendance would be looked for under a meeting that never ran.
    """
    if not recreated_details:
        return
    now = datetime.utcnow()
    for detail in recreated_details:
        try:
            session_number = int(detail.get('session_number') or 0)
        except (TypeError, ValueError):
            continue
        if session_number <= 0:
            continue
        update = {}
        for column in ('graph_event_id', 'join_url', 'online_meeting_id'):
            value = clean_str(detail.get(column))
            if value:
                update[column] = value
        if not update:
            continue
        update['updated_at'] = now
        update_authoring_rows(
            LIVE_SESSION_OCCURRENCES_TABLE,
            'live_session_id = %s and session_number = %s',
            [live_session_id, session_number],
            update,
        )


def live_session_meeting_groups(series, occurrences):
    """(Graph meeting path, the occurrences it holds) for one live-session series.

    Normally a single pair -- the series meeting and every session in it. A
    session recreated on its own event carries its own online meeting, and Graph
    lists a meeting's attendance, transcripts and recordings only under the
    meeting that ran, so those sessions are asked for separately.
    """
    organizer = clean_str(series.get('organizer_email'))
    series_meeting_id = clean_str(series.get('online_meeting_id'))
    series_join_url = clean_str(series.get('join_url'))
    shared = []
    own = []
    for row in occurrences:
        own_meeting_id = clean_str(row.get('online_meeting_id'))
        if not own_meeting_id or own_meeting_id == series_meeting_id:
            shared.append(row)
        else:
            own.append(row)
    groups = []
    if series_meeting_id and (shared or not own):
        groups.append((teams_meeting_base_path(organizer, series_meeting_id, series_join_url), shared))
    for row in own:
        groups.append((
            teams_meeting_base_path(
                organizer,
                clean_str(row.get('online_meeting_id')),
                clean_str(row.get('join_url')) or series_join_url,
            ),
            [row],
        ))
    return groups


@csrf_exempt
def curriculum_teams_meeting(request):
    """
    Create a calendar-backed Teams meeting for a Module Builder live session.

    The event endpoint sends real calendar invitations. Meeting-policy options
    that Graph cannot set on a calendar event are returned as a warning and are
    still persisted by the frontend for visibility.
    """
    from coach_api.views import get_graph_settings, has_graph_credentials, microsoft_graph_request

    graph_settings = get_graph_settings()
    default_organizer = teams_meeting_default_organizer()
    if request.method == 'GET':
        return JsonResponse({
            'configured': has_graph_credentials(),
            'defaultOrganizer': default_organizer,
            # The organizer is the one meeting field a user must not be able to
            # change: the application access policy that lets the LMS turn on
            # recording is granted to that one mailbox. The form renders it
            # read-only when this is true rather than hiding it, because which
            # calendar the series lands in is still worth seeing.
            'organizerLocked': bool(default_organizer),
            'timeZone': graph_settings.get('timezone') or 'GMT Standard Time',
            'timeZoneIana': graph_timezone_iana(graph_settings),
        })
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    if not has_graph_credentials():
        return json_error('Microsoft Graph credentials are not configured.', status=503)

    payload = json_body(request)
    if not isinstance(payload, dict):
        return json_error('A valid JSON body is required.')
    organizer = teams_new_meeting_organizer(payload.get('organizerEmail'))
    if not organizer:
        return json_error(
            'Organizer email is required. Add it here or configure MICROSOFT_TEAMS_ORGANIZER_EMAIL.',
            status=400,
        )

    try:
        event_payload, attendees, presenters, utc_start, duration, repeat, occurrences = teams_event_payload(payload, graph_settings)
    except (TypeError, ValueError) as exc:
        return json_error(str(exc), status=400)

    owner_key = urllib_parse.quote(organizer, safe='')
    try:
        event = microsoft_graph_request('POST', f'users/{owner_key}/events', payload=event_payload)
    except RuntimeError as exc:
        logger.warning('Unable to create Module Builder Teams event: %s', exc)
        return json_error('Microsoft Teams could not create the meeting.', status=502, detail=str(exc))

    event_id = clean_str(event.get('id'))
    online_meeting = event.get('onlineMeeting') or {}
    join_url = clean_str(online_meeting.get('joinUrl'))
    if event_id and not join_url:
        try:
            event_key = urllib_parse.quote(event_id, safe='')
            event = microsoft_graph_request('GET', f'users/{owner_key}/events/{event_key}')
            online_meeting = event.get('onlineMeeting') or {}
            join_url = clean_str(online_meeting.get('joinUrl'))
        except RuntimeError:
            pass

    warnings = []
    lobby_choice = clean_str(payload.get('lobbyBypass')).lower() or 'invited'
    if lobby_choice not in TEAMS_LOBBY_VALUES:
        lobby_choice = 'invited'
    recording = clean_str(payload.get('recording')).lower() or 'none'
    spoken_language = clean_str(payload.get('spokenLanguage')) or 'en-GB'
    meeting_options = {
        'organizer': organizer,
        'recording': recording,
        'lobby_bypass': lobby_choice,
        'spoken_language': spoken_language,
        'presenters': presenters,
    }
    recreated_details = []
    # Graph has just built a plain weekly series. Move its occurrences onto the
    # wizard's holiday-shifted dates now, otherwise the calendar keeps sessions on
    # holidays the wizard already moved them off and the two disagree from day one.
    if event_id:
        shift_warnings, recreated_details = apply_teams_occurrence_shifts(
            owner_key,
            urllib_parse.quote(event_id, safe=''),
            clean_str(payload.get('title')) or 'Live session',
            teams_shifted_occurrence_targets(payload, duration),
            attendees,
            meeting_options,
        )
        for shift_warning in shift_warnings:
            message = clean_str(shift_warning.get('message'))
            detail = clean_str(shift_warning.get('detail'))
            warnings.append(f'{message} ({detail})' if detail else message)
    # Calendar event creation reliably creates the Teams link and invitations, at
    # the tenant's default options. Recording, transcription, the lobby and who
    # presents are set on the onlineMeeting behind it, which needs
    # OnlineMeetings.ReadWrite.All and an application access policy on top.
    settings_applied, graph_meeting, option_warnings = apply_teams_meeting_options(
        organizer,
        join_url,
        recording=recording,
        lobby_bypass=lobby_choice,
        spoken_language=spoken_language,
        attendees=attendees,
        presenters=presenters,
    )
    for option_warning in option_warnings:
        message = clean_str(option_warning.get('message'))
        detail = clean_str(option_warning.get('detail'))
        warnings.append(f'{message} ({detail})' if detail else message)
    meeting_options_url = clean_str(graph_meeting.get('meetingOptionsWebUrl'))
    meeting_id = clean_str(graph_meeting.get('id'))
    if not join_url:
        warnings.append('Microsoft Graph created the calendar event but has not returned the Teams join URL yet.')

    event['_meetingOptionsUrl'] = meeting_options_url
    try:
        live_session_id, tracked_occurrences = persist_live_session_series(
            payload,
            event,
            warnings,
            graph_settings,
            organizer,
            attendees,
            presenters,
            clean_str(graph_meeting.get('id')),
        )
        persist_recreated_occurrence_details(live_session_id, recreated_details)
    except Exception:
        logger.exception('Teams meeting was created, but its live_sessions record could not be saved.')
        return json_error(
            'The Teams meeting was created, but the LMS could not save its live-session record.',
            status=500,
            meetingCreated=True,
            eventId=event_id,
            joinUrl=join_url,
        )

    return JsonResponse({
        'created': True,
        'meeting': {
            'liveSessionId': live_session_id,
            'eventId': event_id,
            'onlineMeetingId': clean_str(graph_meeting.get('id')),
            'joinUrl': join_url,
            'webLink': clean_str(event.get('webLink')),
            'meetingOptionsUrl': meeting_options_url,
            'organizerEmail': organizer,
            'attendees': attendees,
            'presenters': presenters,
            'startDateTimeUtc': utc_start.isoformat(),
            'durationMinutes': duration,
            'repeat': repeat,
            'repeatOccurrences': occurrences if repeat != 'none' else 1,
            'trackedOccurrences': tracked_occurrences,
            'provider': 'Microsoft Teams',
            'trackingReady': bool(meeting_id),
            'settingsApplied': settings_applied,
        },
        'warnings': warnings,
    }, status=201)


def closest_live_occurrence(occurrences, timestamp):
    if not occurrences or not timestamp:
        return None
    comparable_timestamp = timestamp.replace(tzinfo=None)

    def distance(row):
        scheduled = row.get('scheduled_start') or timestamp
        return abs((scheduled.replace(tzinfo=None) - comparable_timestamp).total_seconds())

    return min(
        occurrences,
        key=distance,
    )


def attendance_identity(record):
    identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
    for key in ('user', 'guest', 'phone', 'encrypted'):
        value = identity.get(key)
        if isinstance(value, dict):
            display_name = clean_str(value.get('displayName') or value.get('name'))
            identity_id = clean_str(value.get('id'))
            if display_name or identity_id:
                return display_name, identity_id
    return '', ''


def attendance_display_name(record):
    if not isinstance(record, dict):
        return ''
    display_name, _identity_id = attendance_identity(record)
    if display_name:
        return display_name
    for key in ('displayName', 'participantDisplayName', 'name'):
        display_name = clean_str(record.get(key))
        if display_name:
            return display_name
    email = clean_str(record.get('emailAddress') or record.get('email')).lower()
    if email and '@' in email:
        local = email.split('@', 1)[0]
        return ' '.join(part.capitalize() for part in re.split(r'[._-]+', local) if part)
    return ''


def attendance_interval_seconds(intervals):
    total = 0
    for interval in intervals if isinstance(intervals, list) else []:
        if not isinstance(interval, dict):
            continue
        start = parse_graph_datetime(interval.get('joinDateTime'))
        end = parse_graph_datetime(interval.get('leaveDateTime'))
        if start and end and end >= start:
            total += int((end - start).total_seconds())
    return total


@csrf_exempt
def curriculum_teams_meeting_schedule(request, live_session_id):
    """Update the calendar-backed Teams event when the module schedule shifts."""
    from coach_api.views import get_graph_settings, has_graph_credentials, microsoft_graph_request

    ensure_live_session_tracking_tables()
    series_rows = authoring_fetch_all(LIVE_SESSIONS_TABLE, 'id = %s', [live_session_id])
    if not series_rows:
        return json_error('Live session series not found.', status=404)
    if request.method != 'PATCH':
        return json_error('Method not allowed.', status=405)
    if not has_graph_credentials():
        return json_error('Microsoft Graph credentials are not configured.', status=503)

    payload = json_body(request)
    if not isinstance(payload, dict):
        return json_error('A valid JSON body is required.')
    series = series_rows[0]
    # The stored organizer, never the caller's. This event already exists on one
    # mailbox, and asking Graph for it on another is a 404 that would strand a
    # live series -- so pinning an organizer changes where *new* meetings are
    # created and leaves every series already running on its own calendar.
    organizer = clean_str(series.get('organizer_email')) or teams_meeting_default_organizer()
    event_id = clean_str(payload.get('eventId') or series.get('graph_event_id'))
    if not organizer or not event_id:
        return json_error('This Teams meeting is missing organizer or calendar event identifiers.', status=409)

    graph_settings = get_graph_settings()
    title = clean_str(payload.get('title') or series.get('module_title') or 'Live session')
    local_start_raw = clean_str(payload.get('localStartDateTime'))
    utc_start_raw = clean_str(payload.get('startDateTimeUtc'))
    try:
        local_start = datetime.fromisoformat(local_start_raw)
        utc_start = datetime.fromisoformat(utc_start_raw.replace('Z', '+00:00'))
    except ValueError as exc:
        return json_error('A valid meeting start date and time is required.', status=400, detail=str(exc))

    # The invitation list is optional here: a caller that only shifts dates must
    # not have to resend it, and one that corrects who presents must not have to
    # recreate the meeting to do it. Absent keys keep the stored lists.
    stored_attendees = teams_series_email_list(series.get('attendees'))
    stored_presenters = teams_series_email_list(series.get('presenters'))
    people_changed = 'attendees' in payload or 'presenters' in payload
    try:
        attendees = teams_attendee_emails(payload['attendees']) if 'attendees' in payload else stored_attendees
        presenters = teams_attendee_emails(payload['presenters']) if 'presenters' in payload else stored_presenters
    except (TypeError, ValueError) as exc:
        return json_error(str(exc), status=400)
    invited_people = list(dict.fromkeys([*presenters, *attendees]))

    duration = max(15, min(1440, int(payload.get('durationMinutes') or series.get('duration_minutes') or 60)))
    repeat = clean_str(payload.get('repeat') or series.get('repeat_pattern')).lower() or 'none'
    if repeat not in TEAMS_REPEAT_VALUES:
        return json_error('Unsupported repeat option.', status=400)
    occurrences = max(1, min(52, int(payload.get('repeatOccurrences') or series.get('repeat_occurrences') or 1)))
    # Holiday shifts push later sessions beyond the Nth weekly slot, so the recurrence
    # range must span the shifted end date instead of the plain session count. Sizing it
    # by session count leaves the trailing shifted dates with no instance to move onto.
    recurrence_slots = teams_recurrence_slot_count(payload, local_start, repeat, occurrences)
    event_patch = {
        'subject': title,
        'start': {
            'dateTime': local_start.replace(second=0, microsecond=0).isoformat(timespec='seconds'),
            'timeZone': graph_settings.get('timezone') or series.get('timezone') or 'GMT Standard Time',
        },
        'end': {
            'dateTime': (local_start + timedelta(minutes=duration)).replace(second=0, microsecond=0).isoformat(timespec='seconds'),
            'timeZone': graph_settings.get('timezone') or series.get('timezone') or 'GMT Standard Time',
        },
    }
    if people_changed:
        event_patch['attendees'] = [
            {'emailAddress': {'address': email, 'name': email.split('@', 1)[0]}, 'type': 'required'}
            for email in invited_people
        ]
    recurrence = teams_event_recurrence(repeat, local_start, max(2, recurrence_slots))
    event_patch['recurrence'] = recurrence if repeat != 'none' else None

    owner_key = urllib_parse.quote(organizer, safe='')
    event_key = urllib_parse.quote(event_id, safe='')
    try:
        event = microsoft_graph_request('PATCH', f'users/{owner_key}/events/{event_key}', payload=event_patch)
        if not isinstance(event, dict):
            event = microsoft_graph_request('GET', f'users/{owner_key}/events/{event_key}')
    except RuntimeError as exc:
        logger.warning('Unable to update Module Builder Teams event schedule: %s', exc)
        return json_error('Microsoft Teams could not update the meeting schedule.', status=502, detail=str(exc))

    meeting_options = {
        'organizer': organizer,
        'recording': clean_str(series.get('recording')).lower() or 'none',
        'lobby_bypass': clean_str(series.get('lobby_bypass')).lower() or 'invited',
        'spoken_language': clean_str(series.get('spoken_language')) or 'en-GB',
        'presenters': presenters,
    }
    warnings, recreated_details = apply_teams_occurrence_shifts(
        owner_key,
        event_key,
        title,
        teams_shifted_occurrence_targets(payload, duration),
        invited_people,
        meeting_options,
    )

    join_url = clean_str((event.get('onlineMeeting') or {}).get('joinUrl')) or clean_str(series.get('join_url'))
    # Re-applied on every save, not only when the people change. Graph resets an
    # onlineMeeting's options to the tenant defaults whenever it hands out a new
    # one, so a series that was only ever configured at creation quietly loses its
    # automatic recording, its transcript and its presenter roles later on.
    _applied, graph_meeting, option_warnings = apply_teams_meeting_options(
        organizer,
        join_url,
        recording=meeting_options['recording'],
        lobby_bypass=meeting_options['lobby_bypass'],
        spoken_language=meeting_options['spoken_language'],
        attendees=invited_people,
        presenters=presenters,
        online_meeting_id=series.get('online_meeting_id'),
    )
    warnings.extend(option_warnings)
    occurrence_rows = replace_live_session_occurrences(
        live_session_id,
        payload,
        utc_start,
        duration,
        repeat,
        occurrences,
        event_id=event_id,
        join_url=join_url,
    )
    persist_recreated_occurrence_details(live_session_id, recreated_details)
    series_update = {
        'online_meeting_id': clean_str(graph_meeting.get('id')) or clean_str(series.get('online_meeting_id')),
        'module_title': title,
        'start_datetime': utc_start,
        'duration_minutes': duration,
        'repeat_pattern': repeat,
        'repeat_occurrences': occurrences if repeat != 'none' else 1,
        'join_url': join_url,
        'web_link': clean_str(event.get('webLink')) or clean_str(series.get('web_link')),
        'updated_at': datetime.utcnow(),
    }
    if people_changed:
        series_update['attendees'] = json_db_value(attendees)
        series_update['presenters'] = json_db_value(presenters)
    update_authoring_rows(LIVE_SESSIONS_TABLE, 'id = %s', [live_session_id], series_update)
    return JsonResponse({
        'updated': True,
        'meeting': {
            'liveSessionId': live_session_id,
            'eventId': event_id,
            'joinUrl': join_url,
            'webLink': clean_str(event.get('webLink')) or clean_str(series.get('web_link')),
            'startDateTimeUtc': utc_start.isoformat(),
            'durationMinutes': duration,
            'repeat': repeat,
            'repeatOccurrences': occurrences if repeat != 'none' else 1,
            'trackedOccurrences': len(occurrence_rows),
            'attendees': attendees,
            'presenters': presenters,
        },
        'warnings': warnings,
    })


def upsert_live_session_artifact(occurrence, artifact_type, artifact):
    graph_id = clean_str(artifact.get('id'))
    if not graph_id:
        return False
    authoring_upsert(LIVE_SESSION_ARTIFACTS_TABLE, ['occurrence_id', 'artifact_type', 'graph_artifact_id'], {
        'id': f'ART-{uuid.uuid4().hex.upper()}',
        'occurrence_id': occurrence['id'],
        'artifact_type': artifact_type,
        'graph_artifact_id': graph_id,
        'call_id': clean_str(artifact.get('callId')),
        'content_correlation_id': clean_str(artifact.get('contentCorrelationId')),
        'content_url': clean_str(
            artifact.get('transcriptContentUrl') if artifact_type == 'transcript'
            else artifact.get('recordingContentUrl')
        ),
        'created_datetime': parse_graph_datetime(artifact.get('createdDateTime')),
        'end_datetime': parse_graph_datetime(artifact.get('endDateTime')),
        'metadata': json_db_value(artifact),
    })
    return True


@csrf_exempt
def curriculum_teams_meeting_artifacts(request, live_session_id):
    """Read the tracked lecture plan or pull completed artifacts from Graph."""
    from coach_api.views import has_graph_credentials, microsoft_graph_request

    ensure_live_session_tracking_tables()
    series_rows = authoring_fetch_all(LIVE_SESSIONS_TABLE, 'id = %s', [live_session_id])
    if not series_rows:
        return json_error('Live session series not found.', status=404)
    series = series_rows[0]
    occurrences = authoring_fetch_all(
        LIVE_SESSION_OCCURRENCES_TABLE,
        'live_session_id = %s',
        [live_session_id],
        'session_number asc',
    )
    if request.method == 'GET':
        for occurrence in occurrences:
            occurrence['attendance'] = authoring_fetch_all(
                LIVE_SESSION_ATTENDANCE_TABLE, 'occurrence_id = %s', [occurrence['id']], 'display_name asc'
            )
            for attendance in occurrence['attendance']:
                attendance['intervals'] = parse_json_value(attendance.get('intervals'), [])
                attendance['raw_data'] = parse_json_value(attendance.get('raw_data'), {})
                if not clean_str(attendance.get('display_name')):
                    attendance['display_name'] = attendance_display_name({
                        **attendance['raw_data'],
                        'emailAddress': attendance.get('email') or attendance['raw_data'].get('emailAddress'),
                    })
            occurrence['artifacts'] = authoring_fetch_all(
                LIVE_SESSION_ARTIFACTS_TABLE, 'occurrence_id = %s', [occurrence['id']], 'artifact_type asc'
            )
            for artifact in occurrence['artifacts']:
                artifact['metadata'] = parse_json_value(artifact.get('metadata'), {})
        return JsonResponse({
            'series': stamp_live_session_instants(series),
            'occurrences': [stamp_live_session_instants(occurrence) for occurrence in occurrences],
        })
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    if not has_graph_credentials():
        return json_error('Microsoft Graph credentials are not configured.', status=503)
    organizer = clean_str(series.get('organizer_email'))
    meeting_id = clean_str(series.get('online_meeting_id'))
    join_url = clean_str(series.get('join_url'))
    if organizer and not meeting_id and join_url:
        try:
            graph_meeting = teams_online_meeting_from_join_url(organizer, join_url)
        except RuntimeError as exc:
            logger.warning('Unable to backfill onlineMeeting ID for %s: %s', live_session_id, exc)
            return json_error(
                'The Teams meeting exists, but Microsoft Graph cannot resolve it for tracking. '
                'Grant OnlineMeetings.Read.All and an application access policy to the organizer, then retry.',
                status=409,
                detail=str(exc),
            )
        meeting_id = clean_str(graph_meeting.get('id'))
        if meeting_id:
            update_authoring_rows(LIVE_SESSIONS_TABLE, 'id = %s', [live_session_id], {
                'online_meeting_id': meeting_id,
                'meeting_options_url': clean_str(graph_meeting.get('meetingOptionsWebUrl')) or series.get('meeting_options_url'),
                'updated_at': datetime.utcnow(),
            })
            # A series that only just became resolvable is a series whose options
            # were never applied: the lookup that failed at creation is the same
            # one that gates the patch, so its recording, transcription, lobby and
            # presenter roles are still sitting at the tenant defaults. This is
            # the first moment the LMS can put them right, so it does -- otherwise
            # granting the access policy fixes the tracking and silently leaves
            # every meeting still recording nothing.
            reapplied, _meeting, reapply_warnings = apply_teams_meeting_options(
                organizer,
                join_url,
                recording=clean_str(series.get('recording')).lower() or 'none',
                lobby_bypass=clean_str(series.get('lobby_bypass')).lower() or 'invited',
                spoken_language=clean_str(series.get('spoken_language')) or 'en-GB',
                attendees=teams_series_email_list(series.get('attendees')),
                presenters=teams_series_email_list(series.get('presenters')),
                online_meeting_id=meeting_id,
            )
            if not reapplied:
                logger.warning(
                    'Resolved the onlineMeeting for %s but could not re-apply its options: %s',
                    live_session_id,
                    '; '.join(clean_str(item.get('detail')) for item in reapply_warnings),
                )
    if not organizer or not meeting_id:
        return json_error(
            'The Teams meeting exists, but its online meeting ID is not available yet. '
            'Grant OnlineMeetings.Read.All and an application access policy to the organizer, then retry.',
            status=409,
        )
    # The lookup above may have just resolved the meeting behind the series. Keep
    # the loaded row in step with it, or the grouping below reads the blank value
    # the row was loaded with and asks Graph for nothing at all.
    series['online_meeting_id'] = meeting_id
    errors = []
    synced = {'attendanceReports': 0, 'attendanceRecords': 0, 'transcripts': 0, 'recordings': 0}
    now = datetime.utcnow()

    # Graph answers for the meeting that ran, and a session the wizard had to move
    # can be an event of its own with an online meeting of its own (see
    # apply_teams_occurrence_shifts). Asking the series for that session's
    # attendance, transcript or recording returns nothing at all.
    for base, group in live_session_meeting_groups(series, occurrences):
        try:
            response = microsoft_graph_request('GET', f'{base}/attendanceReports')
            for report in response.get('value') or []:
                report_id = clean_str(report.get('id'))
                report_start = parse_graph_datetime(report.get('meetingStartDateTime'))
                occurrence = closest_live_occurrence(group, report_start)
                if not occurrence or not report_id:
                    continue
                report_key = urllib_parse.quote(report_id, safe='')
                detail = microsoft_graph_request('GET', f'{base}/attendanceReports/{report_key}?$expand=attendanceRecords')
                records = detail.get('attendanceRecords') or []
                update_authoring_rows(LIVE_SESSION_OCCURRENCES_TABLE, 'id = %s', [occurrence['id']], {
                    'attendance_report_id': report_id,
                    'participant_count': int(detail.get('totalParticipantCount') or len(records)),
                    'actual_start': parse_graph_datetime(detail.get('meetingStartDateTime')),
                    'actual_end': parse_graph_datetime(detail.get('meetingEndDateTime')),
                    'status': 'completed',
                    'artifacts_synced_at': now,
                    'last_sync_error': '',
                })
                for record in records:
                    display_name, identity_id = attendance_identity(record)
                    display_name = display_name or attendance_display_name(record)
                    graph_record_id = clean_str(record.get('id') or identity_id or record.get('emailAddress'))
                    stable_key = graph_record_id or uuid.uuid4().hex
                    authoring_upsert(LIVE_SESSION_ATTENDANCE_TABLE, ['id'], {
                        'id': f'ATT-{uuid.uuid5(uuid.NAMESPACE_URL, occurrence["id"] + stable_key).hex.upper()}',
                        'occurrence_id': occurrence['id'],
                        'graph_record_id': graph_record_id,
                        'email': clean_str(record.get('emailAddress')).lower(),
                        'display_name': display_name,
                        'role': clean_str(record.get('role')),
                        'total_attendance_seconds': attendance_interval_seconds(record.get('attendanceIntervals')),
                        'intervals': json_db_value(record.get('attendanceIntervals') or []),
                        'raw_data': json_db_value(record),
                    })
                    synced['attendanceRecords'] += 1
                synced['attendanceReports'] += 1
        except RuntimeError as exc:
            errors.append(f'Attendance: {exc}')

        for artifact_type, endpoint in (('transcript', 'transcripts'), ('recording', 'recordings')):
            try:
                response = microsoft_graph_request('GET', f'{base}/{endpoint}')
                for artifact in response.get('value') or []:
                    timestamp = (
                        parse_graph_datetime(artifact.get('endDateTime'))
                        or parse_graph_datetime(artifact.get('createdDateTime'))
                    )
                    occurrence = closest_live_occurrence(group, timestamp)
                    if occurrence and upsert_live_session_artifact(occurrence, artifact_type, artifact):
                        synced[f'{artifact_type}s'] += 1
                        update_authoring_rows(
                            LIVE_SESSION_OCCURRENCES_TABLE,
                            'id = %s',
                            [occurrence['id']],
                            {'artifacts_synced_at': now, 'last_sync_error': ''},
                        )
            except RuntimeError as exc:
                errors.append(f'{artifact_type.title()}: {exc}')

    try:
        from learner_api.teams_attendance import sync_verified_teams_attendance_reporting

        synced['reportingRows'] = sync_verified_teams_attendance_reporting(
            module_refs=[clean_str(series.get('module_catalogue_id'))],
        )
    except Exception as exc:
        logger.exception('Unable to refresh the learner attendance reporting table.')
        errors.append(f'Attendance reporting: {exc}')

    return JsonResponse({'synced': synced, 'errors': errors, 'partial': bool(errors)}, status=207 if errors else 200)


@require_GET
def curriculum_teams_meeting_artifact_content(request, live_session_id, artifact_id):
    """Proxy a tracked transcript or recording without exposing a Graph token."""
    from coach_api.views import get_graph_settings, microsoft_graph_token

    ensure_live_session_tracking_tables()
    series_rows = authoring_fetch_all(LIVE_SESSIONS_TABLE, 'id = %s', [live_session_id])
    if not series_rows:
        return json_error('Live session series not found.', status=404)
    series = series_rows[0]
    occurrences = authoring_fetch_all(
        LIVE_SESSION_OCCURRENCES_TABLE,
        'live_session_id = %s',
        [live_session_id],
    )
    occurrence_ids = {clean_str(row.get('id')) for row in occurrences}
    artifacts = authoring_fetch_all(LIVE_SESSION_ARTIFACTS_TABLE, 'id = %s', [artifact_id])
    artifact = artifacts[0] if artifacts else None
    if not artifact or clean_str(artifact.get('occurrence_id')) not in occurrence_ids:
        return json_error('Meeting artifact not found.', status=404)

    artifact_type = clean_str(artifact.get('artifact_type')).lower()
    endpoint = 'transcripts' if artifact_type == 'transcript' else 'recordings' if artifact_type == 'recording' else ''
    if not endpoint:
        return json_error('Unsupported meeting artifact.', status=400)

    # A recreated session's transcript and recording live under its own meeting,
    # so the identifiers come from the occurrence the artifact belongs to and fall
    # back to the series only for the sessions that share the series' meeting.
    occurrence = next(
        (row for row in occurrences if clean_str(row.get('id')) == clean_str(artifact.get('occurrence_id'))),
        {},
    )
    occurrence_meeting_id = clean_str(occurrence.get('online_meeting_id'))
    organizer = clean_str(series.get('organizer_email'))
    meeting_id = occurrence_meeting_id or clean_str(series.get('online_meeting_id'))
    join_url = (
        (clean_str(occurrence.get('join_url')) if occurrence_meeting_id else '')
        or clean_str(series.get('join_url'))
    )
    owner_id = teams_online_meeting_owner_id(organizer, join_url)
    graph_artifact_id = clean_str(artifact.get('graph_artifact_id'))
    if not owner_id or not meeting_id or not graph_artifact_id:
        return json_error('The meeting artifact is missing its Graph identifiers.', status=409)

    path = (
        f'users/{urllib_parse.quote(owner_id, safe="")}/onlineMeetings/'
        f'{urllib_parse.quote(meeting_id, safe="")}/{endpoint}/'
        f'{urllib_parse.quote(graph_artifact_id, safe="")}/content'
    )
    graph_settings = get_graph_settings()
    url = f'{graph_settings["base_url"].rstrip("/")}/{path}'
    request_headers = {
        'Authorization': f'Bearer {microsoft_graph_token()}',
        'Accept': 'text/vtt' if artifact_type == 'transcript' else 'video/mp4',
    }
    # <video preload="metadata"> and its seek bar both depend on being able to
    # ask for a byte range: without one it has to fetch the whole recording
    # before it can show a duration or play a second of it. Graph's own
    # /content route understands Range the same way a plain file download
    # does, so the browser's header is forwarded verbatim and Graph's answer
    # (200 or 206) decides what comes back -- this never guesses a range
    # itself, only relays the one the browser already asked for.
    range_header = clean_str(request.META.get('HTTP_RANGE')) if artifact_type == 'recording' else ''
    if range_header:
        request_headers['Range'] = range_header
    graph_request = urllib_request.Request(url, headers=request_headers, method='GET')
    try:
        graph_response = urllib_request.urlopen(graph_request, timeout=45)
    except urllib_error.HTTPError as exc:
        if exc.code == 416 and artifact_type == 'recording':
            response = HttpResponse(status=416)
            content_range = exc.headers.get('Content-Range')
            if content_range:
                response['Content-Range'] = content_range
            return response
        detail = exc.read().decode('utf-8', errors='ignore')
        logger.warning('Unable to fetch Teams %s content: %s %s', artifact_type, exc.code, detail)
        return json_error(f'Microsoft Graph could not return the {artifact_type} content.', status=exc.code)
    except urllib_error.URLError as exc:
        logger.warning('Unable to fetch Teams %s content: %s', artifact_type, exc)
        return json_error(f'Microsoft Graph could not return the {artifact_type} content.', status=502)

    content_type = graph_response.headers.get('Content-Type') or ('text/vtt' if artifact_type == 'transcript' else 'video/mp4')
    filename = f'{live_session_id}-{artifact_type}.{"vtt" if artifact_type == "transcript" else "mp4"}'
    if artifact_type == 'recording':
        # Streamed straight through rather than buffered -- a recording can run
        # to hundreds of MB, and FileResponse cannot help here anyway: it only
        # learns a Content-Length by seeking the file it is given, and this one
        # is a live, one-way socket read with no seek of its own.
        response = StreamingHttpResponse(
            iter(lambda: graph_response.read(65536), b''),
            status=graph_response.status,
            content_type=content_type,
        )
        response['Accept-Ranges'] = 'bytes'
        content_length = graph_response.headers.get('Content-Length')
        if content_length:
            response['Content-Length'] = content_length
        content_range = graph_response.headers.get('Content-Range')
        if content_range:
            response['Content-Range'] = content_range
        as_attachment = clean_str(request.GET.get('preview')).lower() not in {'1', 'true', 'yes'}
        response['Content-Disposition'] = (
            f'{"attachment" if as_attachment else "inline"}; filename="{filename}"'
        )
        return response
    content = graph_response.read()
    graph_response.close()
    response = HttpResponse(content, content_type=content_type)
    response['Content-Disposition'] = f'inline; filename="{filename}"'
    return response


def safe_float(value, default=0.0):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if number != number or number in (float('inf'), float('-inf')):
        return default
    return number


def parse_client_event_time(value):
    parsed = parse_graph_datetime(value)
    if not parsed:
        return datetime.utcnow()
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    return parsed


@csrf_exempt
def curriculum_teams_recording_events(request, live_session_id, artifact_id):
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')

    ensure_live_session_tracking_tables()
    series_rows = authoring_fetch_all(LIVE_SESSIONS_TABLE, 'id = %s', [live_session_id])
    if not series_rows:
        return json_error('Live session series not found.', status=404)
    occurrences = authoring_fetch_all(LIVE_SESSION_OCCURRENCES_TABLE, 'live_session_id = %s', [live_session_id])
    occurrence_by_id = {clean_str(row.get('id')): row for row in occurrences}
    artifacts = authoring_fetch_all(LIVE_SESSION_ARTIFACTS_TABLE, 'id = %s', [artifact_id])
    artifact = artifacts[0] if artifacts else None
    occurrence_id = clean_str((artifact or {}).get('occurrence_id'))
    if not artifact or occurrence_id not in occurrence_by_id:
        return json_error('Meeting recording not found.', status=404)
    if clean_str(artifact.get('artifact_type')).lower() != 'recording':
        return json_error('Only recording artifacts can receive recording tracking events.', status=400)

    viewer = payload.get('viewer') if isinstance(payload.get('viewer'), dict) else {}
    # Who watched is part of a session's record, so the signed-in account is the
    # authority on it: a viewer named in the body is whatever the caller typed.
    # The body is kept only as the fallback for a request with no session.
    account = getattr(request, 'login_account', None)
    if account is not None:
        viewer = {
            'id': clean_str(getattr(account, 'id', '')),
            'email': clean_str(getattr(account, 'email', '')),
            'name': clean_str(getattr(account, 'display_name', '')) or clean_str(getattr(account, 'email', '')),
            'role': clean_str(getattr(account, 'role', '')),
        }
    browser = payload.get('browser') if isinstance(payload.get('browser'), dict) else {}
    preview_session_id = clean_str(payload.get('previewSessionId'))[:128] or uuid.uuid4().hex
    events = payload.get('events') if isinstance(payload.get('events'), list) else []
    if not events:
        return json_error('No recording events were supplied.', status=400)

    now = datetime.utcnow()
    saved = 0
    for event in events[:200]:
        if not isinstance(event, dict):
            continue
        event_type = clean_str(event.get('type') or event.get('eventType'))[:64]
        if not event_type:
            continue
        video_time = max(0.0, safe_float(event.get('videoTimeSeconds') if 'videoTimeSeconds' in event else event.get('videoTime'), 0.0))
        previous_video_time = event.get('previousVideoTimeSeconds') if 'previousVideoTimeSeconds' in event else event.get('previousVideoTime')
        previous_video_time = None if previous_video_time is None else max(0.0, safe_float(previous_video_time, 0.0))
        skip_from = event.get('skipFromSeconds') if 'skipFromSeconds' in event else event.get('skipFrom')
        skip_to = event.get('skipToSeconds') if 'skipToSeconds' in event else event.get('skipTo')
        skip_from = None if skip_from is None else max(0.0, safe_float(skip_from, 0.0))
        skip_to = None if skip_to is None else max(0.0, safe_float(skip_to, 0.0))
        skip_delta = None
        if skip_from is not None and skip_to is not None:
            skip_delta = skip_to - skip_from
        metadata = event.get('metadata') if isinstance(event.get('metadata'), dict) else {}
        insert_row(LIVE_SESSION_RECORDING_EVENTS_TABLE, {
            'id': clean_str(event.get('id'))[:128] or uuid.uuid4().hex,
            'live_session_id': live_session_id,
            'occurrence_id': occurrence_id,
            'artifact_id': artifact_id,
            'preview_session_id': preview_session_id,
            'event_type': event_type,
            'viewer_id': clean_str(viewer.get('id'))[:255],
            'viewer_email': clean_str(viewer.get('email')).lower()[:320],
            'viewer_name': clean_str(viewer.get('name'))[:500],
            'viewer_role': clean_str(viewer.get('role'))[:128],
            'browser_session_id': clean_str(browser.get('sessionId') or payload.get('browserSessionId'))[:128],
            'client_event_id': clean_str(event.get('clientEventId') or event.get('id'))[:128],
            'event_time': parse_client_event_time(event.get('eventTime') or event.get('timestamp')) if event.get('eventTime') or event.get('timestamp') else now,
            'video_time_seconds': video_time,
            'previous_video_time_seconds': previous_video_time,
            'duration_seconds': None if event.get('durationSeconds') is None else max(0.0, safe_float(event.get('durationSeconds'), 0.0)),
            'watched_seconds_delta': max(0.0, safe_float(event.get('watchedSecondsDelta'), 0.0)),
            'playback_rate': max(0.0, safe_float(event.get('playbackRate'), 1.0)),
            'volume': None if event.get('volume') is None else max(0.0, min(1.0, safe_float(event.get('volume'), 0.0))),
            'muted': bool_payload(event.get('muted')) if event.get('muted') is not None else None,
            'skipped': bool_payload(event.get('skipped')) or event_type in {'seeked', 'seek_end', 'skip'},
            'skip_from_seconds': skip_from,
            'skip_to_seconds': skip_to,
            'skip_delta_seconds': skip_delta,
            'viewport_width': parse_int(browser.get('viewportWidth'), 0) or None,
            'viewport_height': parse_int(browser.get('viewportHeight'), 0) or None,
            'user_agent': clean_str(browser.get('userAgent') or request.META.get('HTTP_USER_AGENT'))[:1000],
            'page_url': clean_str(browser.get('pageUrl'))[:1000],
            'referrer': clean_str(browser.get('referrer') or request.META.get('HTTP_REFERER'))[:1000],
            'metadata': json.dumps(metadata),
        })
        saved += 1

    return JsonResponse({'saved': saved, 'previewSessionId': preview_session_id})


def require_fields(payload, fields):
    missing = [field for field in fields if payload.get(field) in (None, '')]
    return missing


def clean_str(value):
    return str(value or '').strip()


def programme_structure_type(payload, fallback='scheduled'):
    value = clean_str((payload or {}).get('structureType') or (payload or {}).get('structure_type') or fallback).lower()
    return value if value in {'scheduled', 'free'} else fallback


def now_iso():
    return datetime.utcnow().isoformat()


def insert_row(table, payload):
    values = filtered_payload(table, payload)
    if not values:
        raise ValueError(f'No writable columns found for {table}.')
    columns = list(values.keys())
    placeholders = ', '.join(['%s'] * len(columns))
    query = (
        f'insert into {table_name(table)} '
        f'({", ".join(quote_ident(column) for column in columns)}) '
        f'values ({placeholders}) returning *'
    )
    try:
        return execute_returning(query, [values[column] for column in columns])[0]
    except DatabaseError as exc:
        if 'no column named' not in str(exc).lower():
            raise
        _TABLE_COLUMNS_CACHE.pop(table, None)
        _TABLE_COLUMNS_CACHE.pop(f'{CURRICULUM_SCHEMA}.{table}', None)
        values = filtered_payload(table, payload)
        if not values:
            raise
        columns = list(values.keys())
        placeholders = ', '.join(['%s'] * len(columns))
        query = (
            f'insert into {table_name(table)} '
            f'({", ".join(quote_ident(column) for column in columns)}) '
            f'values ({placeholders}) returning *'
        )
        return execute_returning(query, [values[column] for column in columns])[0]


def update_rows(table, where_sql, where_params, payload, allow_null_columns=None):
    values = filtered_payload(table, payload, allow_null_columns=allow_null_columns)
    if not values:
        raise ValueError(f'No writable columns found for {table}.')
    assignments = ', '.join(f'{quote_ident(column)} = %s' for column in values)
    query = f'update {table_name(table)} set {assignments} where {where_sql} returning *'
    return execute_returning(query, [*values.values(), *where_params])


def delete_rows(table, where_sql, where_params):
    query = f'delete from {table_name(table)} where {where_sql} returning *'
    return execute_returning(query, where_params)


def row_has_deleted_at(row):
    return bool(row and row.get('deleted_at'))


def soft_delete_payload(table, *, via_parent='', deleted_by='system', extra=None):
    payload = {
        'deleted_at': datetime.utcnow(),
        'deleted_by': clean_str(deleted_by) or 'system',
        'deleted_via_parent': clean_str(via_parent) or '',
        'updated_at': datetime.utcnow(),
        **(extra or {}),
    }
    if has_column(table, 'is_programme_deleted'):
        payload['is_programme_deleted'] = True
    if has_column(table, 'is_archived'):
        payload['is_archived'] = True
    if table == 'programmes':
        if has_column(table, 'status'):
            payload['status'] = 'archived'
        if has_column(table, 'is_active'):
            payload['is_active'] = False
    if has_column(table, 'status') and table in {'cohorts'}:
        payload['status'] = 'archived'
    return payload


def restore_soft_delete_payload(table):
    payload = {'updated_at': datetime.utcnow()}
    if has_column(table, 'deleted_at'):
        payload['deleted_at'] = None
    if has_column(table, 'deleted_by'):
        payload['deleted_by'] = None
    if has_column(table, 'deleted_via_parent'):
        payload['deleted_via_parent'] = None
    if has_column(table, 'is_programme_deleted'):
        payload['is_programme_deleted'] = False
    return payload


def soft_delete_rows(table, where_sql, where_params=None, *, via_parent='', deleted_by='system', extra=None):
    payload = soft_delete_payload(table, via_parent=via_parent, deleted_by=deleted_by, extra=extra)
    if not any(column in column_names(table) for column in payload):
        return []
    active_checks = []
    if has_column(table, 'deleted_at'):
        active_checks.append(f'{quote_ident("deleted_at")} is null')
    if has_column(table, 'is_programme_deleted'):
        active_checks.append(f'{quote_ident("is_programme_deleted")} is distinct from true')
    if not active_checks:
        active_checks.append('1 = 1')
    guarded_where = f'({where_sql}) and (' + ' and '.join(active_checks) + ')'
    return update_rows(table, guarded_where, where_params or [], payload)


def authoring_soft_delete(table, where_sql, params=None, *, via_parent='', deleted_by='system', extra=None):
    ensure_module_authoring_tables()
    return soft_delete_rows(table, where_sql, params or [], via_parent=via_parent, deleted_by=deleted_by, extra=extra)


# A detached row's parent id. These columns are NOT NULL, so an unattached row
# carries the empty string rather than NULL - which is also precisely what
# ``repair_curriculum_parent_links`` already skips, so the orphan sweeper cannot
# destroy library content.
LIBRARY_STATE_DETACHED = 'library'
DETACHED_PARENT_SENTINEL = ''


def detach_to_library_payload(
    table,
    *,
    origin_module_id='',
    origin_module_title='',
    origin_week_id='',
    origin_week_label='',
):
    """Columns that turn an owned row into an unattached, reusable one.

    A library item is deliberately *not* a deleted item: the soft-delete stamps
    are cleared, because the row is no longer archived-under-a-parent, it simply
    has no parent. Origin is denormalised because the whole point is that the
    parent row is going away and its title would otherwise be unrecoverable.

    Every write is guarded by ``has_column`` in the same style as
    ``soft_delete_payload``, so an environment that has not yet run migration
    0053 degrades to a plain detach rather than raising.
    """
    payload = {'updated_at': datetime.utcnow()}
    if has_column(table, 'library_state'):
        payload['library_state'] = LIBRARY_STATE_DETACHED
    if has_column(table, 'detached_at'):
        payload['detached_at'] = datetime.utcnow()
    if has_column(table, 'origin_module_catalogue_id'):
        payload['origin_module_catalogue_id'] = clean_str(origin_module_id)
    if has_column(table, 'origin_module_title'):
        payload['origin_module_title'] = clean_str(origin_module_title)
    if has_column(table, 'origin_week_id'):
        payload['origin_week_id'] = clean_str(origin_week_id)
    if has_column(table, 'origin_week_label'):
        payload['origin_week_label'] = clean_str(origin_week_label)
    # Clear the parent links. Empty string, not NULL: the columns are NOT NULL
    # and the orphan sweeper's own guards test for ''.
    if has_column(table, 'module_catalogue_id'):
        payload['module_catalogue_id'] = DETACHED_PARENT_SENTINEL
    if has_column(table, 'week_id'):
        payload['week_id'] = DETACHED_PARENT_SENTINEL
    # An unattached row is available, not archived.
    if has_column(table, 'deleted_at'):
        payload['deleted_at'] = None
    if has_column(table, 'deleted_by'):
        payload['deleted_by'] = None
    if has_column(table, 'deleted_via_parent'):
        payload['deleted_via_parent'] = None
    if has_column(table, 'is_programme_deleted'):
        payload['is_programme_deleted'] = False
    return payload


def detach_rows_to_library(table, where_sql, where_params=None, **origin):
    """Detach matching rows into the reuse library instead of deleting them."""
    if not table_exists(table):
        return []
    payload = detach_to_library_payload(table, **origin)
    if not any(column in column_names(table) for column in payload):
        return []
    # Already-detached rows keep their original origin stamps: a second detach
    # would overwrite them with the parent that is being removed now, which is
    # not where the content actually came from.
    guarded_where = where_sql
    if has_column(table, 'library_state'):
        guarded_where = (
            f'({where_sql}) and coalesce({quote_ident("library_state")}, %s) <> %s'
        )
    params = list(where_params or [])
    if has_column(table, 'library_state'):
        params = [*params, '', LIBRARY_STATE_DETACHED]
    # allow_null_columns is required, not cosmetic: filtered_payload drops None
    # values, so without it the soft-delete stamps would survive the detach and
    # a programme-archived component would stay archived forever. The real path
    # always hits this - a permanent delete is only allowed on an already
    # archived programme, whose children are all stamped.
    return update_rows(
        table, guarded_where, params, payload,
        allow_null_columns=RESTORE_NULLABLE_COLUMNS,
    )


def is_library_row(row):
    """True when this week/component is detached and held for reuse."""
    return clean_str((row or {}).get('library_state')) == LIBRARY_STATE_DETACHED


def library_sweep_guard(table, where_sql):
    """Narrow a destructive sweep so it can never touch detached library rows."""
    if not has_column(table, 'library_state'):
        return where_sql
    return (
        f"({where_sql}) and coalesce({quote_ident('library_state')}, '') "
        f"<> '{LIBRARY_STATE_DETACHED}'"
    )


def deleted_sql_condition(table, alias=''):
    prefix = f'{alias}.' if alias else ''
    checks = []
    if has_column(table, 'deleted_at'):
        checks.append(f'{prefix}{quote_ident("deleted_at")} is not null')
    if has_column(table, 'is_programme_deleted'):
        checks.append(f'{prefix}{quote_ident("is_programme_deleted")} = true')
    if has_column(table, 'is_archived'):
        checks.append(f'coalesce({prefix}{quote_ident("is_archived")}, false) = true')
    if not checks:
        return 'false'
    return '(' + ' or '.join(checks) + ')'


def append_notes_meta(notes, meta):
    existing = []
    keys = set(meta)
    for line in str(notes or '').splitlines():
        if line.startswith('__') and ':' in line:
            key = line.split(':', 1)[0].strip('_')
            if key in keys:
                continue
        existing.append(line)
    for key, value in meta.items():
        existing.append(f'__{key}: {value}')
    return '\n'.join(line for line in existing if line != '').strip()


def remove_notes_meta(notes, keys):
    blocked = set(keys)
    lines = []
    for line in str(notes or '').splitlines():
        if line.startswith('__') and ':' in line:
            key = line.split(':', 1)[0].strip('_')
            if key in blocked:
                continue
        lines.append(line)
    return '\n'.join(line for line in lines if line != '').strip()


def archive_payload(table, existing_notes=None):
    payload = {}
    if has_column(table, 'status'):
        payload['status'] = 'archived'
    if has_column(table, 'is_archived'):
        payload['is_archived'] = True
    if has_column(table, 'is_active'):
        payload['is_active'] = False
    notes_column = 'notes' if has_column(table, 'notes') else ('Notes' if has_column(table, 'Notes') else None)
    if notes_column:
        payload[notes_column] = append_notes_meta(existing_notes, {'archived': 'true', 'archived_at': now_iso()})
    return payload


def restore_payload(table, existing_notes=None):
    payload = {}
    if has_column(table, 'status'):
        payload['status'] = 'active'
    if has_column(table, 'is_archived'):
        payload['is_archived'] = False
    if has_column(table, 'is_active'):
        payload['is_active'] = True
    notes_column = 'notes' if has_column(table, 'notes') else ('Notes' if has_column(table, 'Notes') else None)
    if notes_column:
        payload[notes_column] = remove_notes_meta(existing_notes, {'archived', 'archived_at'})
    return payload


def parse_json_value(value, fallback):
    if value in (None, ''):
        return fallback
    if isinstance(value, (list, dict)):
        return value
    try:
        return json.loads(value)
    except (TypeError, ValueError):
        return fallback


def parse_int(value, default=0):
    try:
        return int(str(value).strip())
    except (TypeError, ValueError):
        return default


def parse_required_otjh(value):
    """Off-the-job hours a learner must complete for the programme.

    Returns None for a blank or unparseable entry so the column stays NULL: the
    review step distinguishes "no target set" from a target of zero hours, and
    treating a cleared field as 0 would report every programme as already met.
    """
    text = clean_str(value)
    if not text:
        return None
    hours = parse_float(text, -1)
    if hours < 0:
        return None
    return round(hours, 2)


def payload_required_otjh(payload, existing=None):
    """Resolve required_otjh for a write, leaving it untouched when unsent.

    An absent key must not wipe a stored target, so callers that pass this into
    update_rows also pass allow_null_columns=['required_otjh'] — that lets an
    explicitly emptied field clear the column while an omitted one is dropped.
    """
    payload = payload or {}
    for key in ('requiredOtjh', 'required_otjh'):
        if key in payload:
            return parse_required_otjh(payload.get(key))
    if existing is None:
        return None
    return parse_required_otjh((existing or {}).get('required_otjh'))


def parse_float(value, default=0):
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return default


def component_expected_otjh(component, default=2):
    component = component or {}
    if component.get('expectedOtjh') not in (None, ''):
        return parse_float(component.get('expectedOtjh'), default)
    if component.get('expected_otjh') not in (None, ''):
        return parse_float(component.get('expected_otjh'), default)
    return default


def parse_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).strip()).date()
    except ValueError:
        return None


def format_date(value):
    parsed = parse_date(value)
    return parsed.isoformat() if parsed else ''


def calculate_cohort_end_date(start_value, duration_months):
    start = parse_date(start_value)
    months = parse_int(duration_months, 0)
    if not start or months <= 0:
        return None

    # Curriculum convention: a 24 month cohort starting 2026-09-01 ends 2028-08-31.
    month_index = start.month - 1 + months
    year = start.year + month_index // 12
    month = month_index % 12 + 1
    day = min(start.day, calendar.monthrange(year, month)[1])
    return date(year, month, day) - timedelta(days=1)


def holiday_extension_days(holidays, period_start, period_end):
    """Count the selected holiday days inside a delivery period.

    Only the part of a holiday that falls inside ``period_start``..``period_end``
    counts. Weekends are counted too because module session plans work in
    calendar dates: a two week holiday blocks fourteen possible calendar days,
    even if only some of those dates are normal delivery days.
    """
    start = parse_date(period_start)
    end = parse_date(period_end)
    if not start or not end:
        return 0

    days = {day for day in holiday_date_set(holidays) if start <= day <= end}
    return len(days)


def holiday_extension_breakdown(holidays, period_start, period_end):
    """Per-holiday account of what each one takes out of a delivery period.

    The total on its own ("+37 days") is not something a human can check. This
    names each holiday and the days of it that actually landed inside the
    period, so a schedule preview can explain exactly what was skipped.

    Days are attributed to the first holiday that claims them, so overlapping
    holidays add up to the same total the date arithmetic uses rather than
    double-counting the shared days.
    """
    start = parse_date(period_start)
    end = parse_date(period_end)
    if not start or not end:
        return []

    claimed = set()
    breakdown = []
    for item in holidays or []:
        days = sorted(
            day for day in holiday_date_set([item])
            if start <= day <= end and day not in claimed
        )
        if not days:
            continue
        claimed.update(days)
        label = ''
        if isinstance(item, dict):
            label = clean_str(item.get('label') or item.get('name') or item.get('title'))
        breakdown.append({
            'label': label,
            'startDate': format_date(days[0]),
            'endDate': format_date(days[-1]),
            'days': len(days),
        })
    return breakdown


def extend_end_date_for_holidays(base_end_value, holidays, period_start):
    """Push a schedule end date out by the selected holiday days.

    Kept for callers that need a simple date shift. Cohort contract dates do not
    use this; module session planning skips clashing dates directly in
    ``build_module_session_plan``.
    """
    base_end = parse_date(base_end_value)
    if not base_end:
        return None

    return base_end + timedelta(days=holiday_extension_days(holidays, period_start, base_end))


def cohort_applied_holidays(holiday_ids, holiday_rows, period_start, period_end):
    """The holidays that actually apply to a cohort over its base period.

    An empty ``holiday_ids`` means *no* holiday applies. Module schedules only
    skip dates from the explicit cohort selection, so a cohort nobody has picked
    holidays for keeps the plain delivery pattern.

    ``holiday_rows`` may be omitted, in which case the stored holidays are read.
    """
    if holiday_rows is None:
        try:
            holiday_rows = [] if not holiday_table_name() else get_holiday_rows()
        except (Exception, AssertionError):
            holiday_rows = []

    serialized = [serialize_holiday_row(row) for row in (holiday_rows or [])]
    in_period = [
        item for item in serialized
        if date_ranges_overlap(period_start, period_end, item.get('startDate'), item.get('endDate'))
    ]
    selected = {clean_str(item) for item in parse_notes_id_list(holiday_ids)}
    if not selected:
        return []
    return [item for item in in_period if clean_str(item.get('id')) in selected]


def cohort_practical_end_date(start_value, duration_months, holiday_ids=None, holiday_rows=None):
    """A cohort's contracted practical end date.

    Cohort dates are signed contract dates, so selected holidays do not move
    them. Holiday ids are still stored on the cohort because module schedules use
    that selection to skip clashing sessions and extend the affected module plan.
    ``holiday_ids`` and ``holiday_rows`` stay in the signature for older callers.
    """
    return calculate_cohort_end_date(start_value, duration_months)


def parse_epa_months(value):
    """Read an End Point Assessment period in whole months.

    None means "no EPA period recorded", which is not the same as zero: a
    cohort with no EPA period has no apprenticeship end date to show, whereas
    an explicit 0 means the apprenticeship ends when the practical period does.
    """
    if value in (None, ''):
        return None
    months = parse_int(value, -1)
    return months if months >= 0 else None


def payload_epa_months(payload, existing=None):
    """Resolve the EPA period for a write, leaving it untouched when unsent.

    An explicit blank clears the period; an absent key keeps whatever the stored
    row already has, so a partial save cannot drop an authored period.
    """
    for key in ('epaMonths', 'epa_months'):
        if key in (payload or {}):
            return parse_epa_months((payload or {}).get(key))
    return parse_epa_months((existing or {}).get('epa_months'))


def parse_apprenticeship_end_override(value):
    """Read a manually authored apprenticeship end date.

    None means "no override": the calculated date stands. An unparseable value
    is treated the same way rather than raising, so a bad string cannot wedge a
    save — the cohort simply keeps its calculated date.
    """
    if value in (None, ''):
        return None
    return parse_date(value)


def payload_apprenticeship_end_override(payload, existing=None):
    """Resolve the override for a write, leaving it untouched when unsent.

    Mirrors ``payload_epa_months``: an explicit blank clears the override and
    hands the date back to the EPA calculation, while an absent key keeps
    whatever the stored row already has so a partial save cannot drop an
    authored date.
    """
    # The explicit override keys are read first so a payload that round-trips a
    # serialized cohort -- which carries the *effective* apprenticeshipEndDate
    # alongside the authored apprenticeshipEndOverride -- cannot promote a
    # calculated date into an authored one.
    for key in ('apprenticeshipEndOverride', 'apprenticeship_end_override', 'apprenticeshipEndDate', 'apprenticeship_end_date'):
        if key in (payload or {}):
            return parse_apprenticeship_end_override((payload or {}).get(key))
    return parse_apprenticeship_end_override((existing or {}).get('apprenticeship_end_override'))


def apprenticeship_end_override_sent(payload, meta=None):
    """Whether this write carries an apprenticeship end date at all."""
    keys = ('apprenticeshipEndDate', 'apprenticeship_end_date', 'apprenticeshipEndOverride', 'apprenticeship_end_override')
    return any(key in (payload or {}) for key in keys) or 'apprenticeship_end_override' in (meta or {})


def calculate_apprenticeship_end_date(practical_end_value, epa_months):
    """The apprenticeship end date: the practical end date plus the EPA period.

    Unlike ``calculate_cohort_end_date`` this keeps the same day of the month
    and does not subtract a day — the practical period already ended, and the
    EPA window is counted forward from that date. A practical period ending
    2027-03-04 with a 5 month EPA period ends 2027-08-04.
    """
    practical_end = parse_date(practical_end_value)
    months = parse_epa_months(epa_months)
    if not practical_end or not months:
        return None

    month_index = practical_end.month - 1 + months
    year = practical_end.year + month_index // 12
    month = month_index % 12 + 1
    day = min(practical_end.day, calendar.monthrange(year, month)[1])
    return date(year, month, day)


def cohort_apprenticeship_end_date(practical_end_value, epa_months, override=None):
    """The date a cohort's apprenticeship actually ends.

    An authored override wins outright — it is the date the delivery team was
    given, and no whole number of EPA months need land on it. With no override
    the date is calculated from the practical end date plus the EPA period.
    """
    manual = parse_apprenticeship_end_override(override)
    if manual:
        return manual
    return calculate_apprenticeship_end_date(practical_end_value, epa_months)


def cohort_epa_dates(practical_end_value, epa_months, override=None):
    """Resolve the pair of end dates a cohort exposes, as ISO strings.

    The apprenticeship end date is always resolved here rather than read back
    from its ``apprenticeship_end_date`` column: that column is a cache for SQL
    consumers (the enrolment backfill joins on it), and serving the cache would
    surface a stale date whenever the practical end date moved without the EPA
    period being resent. The override column is the authored input and *is* read
    back, which is exactly why the two are kept apart.
    """
    practical_end = format_date(practical_end_value)
    return practical_end, format_date(cohort_apprenticeship_end_date(practical_end, epa_months, override))


WEEKDAY_INDEX = {
    'monday': 0,
    'mon': 0,
    'tuesday': 1,
    'tue': 1,
    'wednesday': 2,
    'wed': 2,
    'thursday': 3,
    'thu': 3,
    'friday': 4,
    'fri': 4,
    'saturday': 5,
    'sat': 5,
    'sunday': 6,
    'sun': 6,
}


def parse_delivery_days(value):
    if isinstance(value, list):
        tokens = value
    else:
        tokens = re.split(r'[,/|+&\s]+', str(value or '').lower())
    days = []
    for token in tokens:
        key = str(token).strip().lower()
        if key in WEEKDAY_INDEX and WEEKDAY_INDEX[key] not in days:
            days.append(WEEKDAY_INDEX[key])
    return days


def build_group_schedule(week_days='', start_time='', end_time='', fallback=''):
    """Format group delivery day and time for API display."""
    days = ', '.join(clean_str(day) for day in week_days if clean_str(day)) if isinstance(week_days, list) else clean_str(week_days)
    start = clean_str(start_time)
    end = clean_str(end_time)
    if days and start and end:
        return f'{days} {start}-{end}'
    if days and start:
        return f'{days} {start}'
    return days or clean_str(fallback)


def schedule_time_parts(value):
    text = clean_str(value)
    match = re.search(r'(\d{1,2}:?\d{2}\s*(?:AM|PM)?)\s*[-–]\s*(\d{1,2}:?\d{2}\s*(?:AM|PM)?)', text, re.I)
    if not match:
        return '', ''
    return clean_str(match.group(1)), clean_str(match.group(2))


def schedule_day_part(value):
    text = clean_str(value)
    if not text:
        return ''
    start, _ = schedule_time_parts(text)
    if start:
        text = text.split(start, 1)[0]
    return clean_str(re.sub(r'[-â€“]+$', '', text).strip(' ,|-'))


def group_schedule_value(group):
    group = group or {}
    return build_group_schedule(
        group.get('session_week_day') or schedule_day_part(group.get('schedule')),
        group.get('session_start_time') or schedule_time_parts(group.get('schedule'))[0],
        group.get('session_end_time') or schedule_time_parts(group.get('schedule'))[1],
        group.get('schedule'),
    )


def holiday_date_set(holidays):
    dates = set()
    for item in holidays or []:
        if isinstance(item, dict):
            start = parse_date(item.get('startDate') or item.get('start_date') or item.get('date'))
            end = parse_date(item.get('endDate') or item.get('end_date') or item.get('date')) or start
        else:
            start = parse_date(item)
            end = start
        if not start:
            continue
        cursor = start
        while cursor <= end:
            dates.add(cursor)
            cursor += timedelta(days=1)
    return dates


def build_module_session_plan(start_value, number_of_sessions, delivery_days, holidays=None):
    start = parse_date(start_value)
    session_count = parse_int(number_of_sessions, 0)
    days = parse_delivery_days(delivery_days)
    warnings = []

    if not start:
        warnings.append('Set module start date before calculating module end date.')
    if session_count <= 0:
        warnings.append('Set a positive number of sessions before calculating module end date.')
    if not days:
        warnings.append('Set group delivery day/time before calculating module end date.')
    if warnings:
        return {
            'sessions': [],
            'skippedHolidays': [],
            'finalEndDate': '',
            'warnings': warnings,
        }

    selected_holidays = holiday_date_set(holidays)
    sessions = []
    skipped = []
    pending_skipped = []
    cursor = start
    guard_days = max(3650, session_count * 21)
    while len(sessions) < session_count and guard_days > 0:
        if cursor.weekday() in days:
            if cursor in selected_holidays:
                skipped.append(cursor.isoformat())
                pending_skipped.append(cursor.isoformat())
            else:
                sessions.append({
                    'sessionNumber': len(sessions) + 1,
                    'date': cursor.isoformat(),
                    'day': cursor.strftime('%A'),
                    'skippedHolidays': pending_skipped,
                })
                pending_skipped = []
        cursor += timedelta(days=1)
        guard_days -= 1

    if len(sessions) < session_count:
        warnings.append('Could not generate the full session plan from the supplied delivery pattern.')

    return {
        'sessions': sessions,
        'skippedHolidays': skipped,
        'finalEndDate': sessions[-1]['date'] if sessions else '',
        'warnings': warnings,
    }


def cohort_delivery_window(cohort):
    """The dates a module placed in ``cohort`` has to fit inside.

    The practical end date is the boundary, not the apprenticeship end: the EPA
    period that follows it carries no delivery. It already has any ticked
    holidays folded in, so a plan that skips them still lands inside the window.
    """
    cohort = cohort or {}
    start = parse_date(cohort.get('startDate') or cohort.get('start_date'))
    end = parse_date(
        cohort.get('practicalEndDate')
        or cohort.get('practical_end_date')
        or cohort.get('endDate')
        or cohort.get('end_date')
    )
    return start, end


def module_cohort_date_error(module_name, start_value, end_value, cohort):
    """Refuse a module whose dates fall outside its cohort's delivery window.

    Three ways out of the window, one message each: starting before the cohort
    opens, starting after it has finished, and -- the case a generated session
    plan reaches on its own -- running past the end. Returns
    ``(message, field)`` or ``None``.
    """
    cohort_start, cohort_end = cohort_delivery_window(cohort)
    module_start = parse_date(start_value)
    module_end = parse_date(end_value)
    label = f'Module "{clean_str(module_name)}"' if clean_str(module_name) else 'The module'

    if module_start and cohort_start and module_start < cohort_start:
        return (
            f'{label} cannot start before the cohort start date ({format_date(cohort_start)}).',
            'startDate',
        )
    if module_start and cohort_end and module_start > cohort_end:
        return (
            f'{label} cannot start after the cohort end date ({format_date(cohort_end)}).',
            'startDate',
        )
    if module_end and cohort_end and module_end > cohort_end:
        return (
            f'{label} cannot finish after the cohort end date ({format_date(cohort_end)}). '
            f'It currently finishes {format_date(module_end)} -- move the start date earlier '
            f'or reduce the number of sessions.',
            'endDate',
        )
    return None


def module_parent_cohort(cohort_id, group_id=''):
    """The cohort a module is placed in, read from the normalized tables.

    A module carries its own cohort id, but a placement that only names the
    group still has a parent cohort -- the group's own.
    """
    row = resolve_cohort_row(cohort_id) if clean_str(cohort_id) else None
    if not row and clean_str(group_id):
        group_row = resolve_group_row(group_id)
        if group_row:
            row = resolve_cohort_row(group_row.get('cohort_id'))
    if not row:
        return None
    return curriculum_cohort_from_authoring_detail(serialize_cohort_authoring_detail(row))


def slugify(value):
    slug = re.sub(r'[^a-z0-9]+', '-', str(value).lower()).strip('-')
    return slug or 'item'


def unique_prefixed_id(prefix, value='', existing_values=None):
    """Canonicalise a requested id, or mint a fresh one that is not taken.

    A canonical request is returned as-is: the id is the caller's assertion of
    identity, so an entity being updated keeps its id whether or not it is
    already stored. ``existing_values`` may be a callable, which is then only
    invoked on the mint path — the id lists for cohorts and groups cost a whole
    table read each (see unique_cohort_id/unique_group_id), and a tree save asks
    for one per cohort and per group while every request is already canonical.
    """
    requested = clean_str(value)
    if re.match(rf'^{re.escape(prefix)}-[A-Z0-9][A-Z0-9_-]*$', requested, re.I):
        return f'{prefix}-{requested.split("-", 1)[1]}'

    values = existing_values() if callable(existing_values) else existing_values
    existing = {clean_str(item) for item in (values or []) if clean_str(item)}
    while True:
        candidate = f'{prefix}-{datetime.utcnow().strftime("%Y%m%d%H%M%S%f")}'
        if candidate not in existing:
            return candidate


def unique_timestamp_prefixed_id(prefix, existing_values=None):
    existing = {clean_str(value) for value in (existing_values or []) if clean_str(value)}
    while True:
        candidate = f'{prefix}-{datetime.utcnow().strftime("%Y%m%d%H%M%S%f")}'
        if candidate not in existing:
            return candidate


def unique_program_id(value, configs):
    return unique_prefixed_id('PROG', value, [programme_config_id(config) for config in configs if programme_config_id(config)])


def unique_ksb_profile_id(value='', existing_values=None):
    requested = clean_str(value)
    existing = {clean_str(value) for value in (existing_values or []) if clean_str(value)}
    if requested.startswith('PROG-'):
        requested = f'KSBP-{requested.removeprefix("PROG-")}'
    return unique_prefixed_id('KSBP', requested, existing)


def existing_training_meta_ids(key):
    return [
        row.get('_meta', {}).get(key)
        for row in get_training_rows()
        if row.get('_meta', {}).get(key)
    ]


def unique_cohort_id(value=''):
    def existing():
        return [detail.get('cohortId') for detail in cohort_authoring_detail_rows() if detail.get('cohortId')]

    return unique_prefixed_id('COHORT', value, existing)


def unique_group_id(value=''):
    def existing():
        return [detail.get('id') for detail in group_authoring_detail_rows() if detail.get('id')]

    return unique_prefixed_id('GROUP', value, existing)


def normalise(value):
    return re.sub(r'[^a-z0-9]+', '', str(value).lower())


def truthy(value):
    return str(value).strip().lower() in {'1', 'true', 'yes', 'y', 'on'}


def falsey(value):
    return str(value).strip().lower() in {'0', 'false', 'no', 'n', 'off'}


def programme_deleted_row(row):
    return bool(row) and (
        row_has_deleted_at(row)
        or truthy(row.get('is_programme_deleted'))
        or truthy(row.get('isProgrammeDeleted'))
        or truthy(row.get('is_deleted'))
        or truthy(row.get('isDeleted'))
    )


def curriculum_row_effectively_deleted(row):
    """Is this curriculum row soft-deleted — directly, or through an ancestor?

    ``deleted_at`` / ``is_programme_deleted`` are the soft-delete source of
    truth (curriculum_api 0040/0041) and ``is_archived`` is the archive signal
    that programmes, and legacy cohorts, carry instead. Parent-driven deletion
    needs no join: the cascade stamps the child row itself and records the
    ancestor in ``deleted_via_parent``, so a row deleted via its programme reads
    as deleted here too.

    This is the predicate the parent-link repair uses to decide what it may
    touch and what it may point at. It never *changes* delete state — restoring
    is a separate, explicit operation (``restore_soft_delete_payload``).
    """
    return programme_deleted_row(row) or truthy(row.get('is_archived'))


def is_operational_training_row(row):
    if programme_deleted_row(row):
        return False
    if truthy(row.get('is_archived')):
        return False

    meta = row.get('_meta', {})
    for key in ('hidden', 'is_hidden', 'deleted', 'is_deleted', 'is_programme_deleted', 'archived', 'is_archived', 'inactive', 'disabled'):
        if key in meta and truthy(meta.get(key)):
            return False

    for key in ('active', 'is_active', 'visible', 'is_visible', 'operational', 'is_operational'):
        if key in meta and falsey(meta.get(key)):
            return False

    return True


def programme_config_explicit_archive_flag(config):
    if not config:
        return None
    for key in ('is_archived', 'is_archive'):
        if key in config:
            return truthy(config.get(key))
    return None


def is_archived_program_config(config):
    # programmes.is_archived is the display source of truth: FALSE means show.
    explicit_archive = programme_config_explicit_archive_flag(config)
    if explicit_archive is not None:
        return explicit_archive
    return bool(config) and (
        row_has_deleted_at(config)
        or truthy(config.get('deleted_at'))
        or truthy(config.get('archived'))
        or clean_str(config.get('status')).lower() == 'archived'
    )


def normalise_programme_status(value, default='active'):
    status = clean_str(value).lower()
    if status == 'archived':
        return status
    if status in {'draft', 'active', 'published', 'planned', 'live'}:
        return 'active'
    return default


def programme_status_is_active(status):
    return normalise_programme_status(status, 'active') == 'active'


def programme_status_is_archived(status):
    return normalise_programme_status(status, 'active') == 'archived'


def programme_status_from_payload(payload, current=None, default='active'):
    current_status = programme_config_status(current) if current else default
    if isinstance(payload, dict) and 'status' in payload:
        return normalise_programme_status(payload.get('status'), current_status)
    return current_status


def programme_config_status(config):
    if is_archived_program_config(config):
        return 'archived'
    if programme_config_explicit_archive_flag(config) is False:
        return 'active'
    status = normalise_programme_status((config or {}).get('status'), '')
    if status:
        return status
    return 'active'


def programme_dependency_counts(identifier, config=None):
    """Count the children that would be orphaned by hard-deleting a programme.

    curriculum.programmes has NO inbound foreign keys, so the database will
    happily delete a programme row and leave its cohorts/groups/modules
    dangling. This is the application-level guard that replaces the protection
    a FK would normally provide.
    """
    candidates = {clean_str(identifier), programme_config_identity(config)}
    candidates = {value for value in candidates if value}
    names = {
        clean_str((config or {}).get('name')),
        clean_str((config or {}).get('standard')),
    }
    names = {value for value in names if value}
    counts = {}
    if not candidates:
        return counts
    placeholders = ', '.join(['%s'] * len(candidates))
    params = list(candidates)
    for table in (
        COHORT_AUTHORING_DETAILS_TABLE,
        GROUPS_TABLE,
        AUTHORING_MODULES_TABLE,
        'week_templates',
        'quizzes',
        FREE_PROGRAMME_COMPONENTS_TABLE,
    ):
        try:
            if not table_exists(table) or not has_column(table, 'programme_id'):
                continue
            rows = fetch_all(
                f'select count(*) as total from {table_name(table)} '
                f'where {quote_ident("programme_id")} in ({placeholders})',
                params,
            )
            total = int((rows[0] or {}).get('total') or 0) if rows else 0
            if total:
                counts[table] = total
        except Exception:
            logger.debug('Could not count %s rows for programme %s.', table, identifier, exc_info=True)
    if names and connection.vendor == 'postgresql':
        try:
            with connection.cursor() as cursor:
                cursor.execute("select to_regclass(%s)", ['"Learner"."learners"'])
                if cursor.fetchone()[0]:
                    name_placeholders = ', '.join(['%s'] * len(names))
                    cursor.execute(
                        f'select count(*) from "Learner"."learners" where programme in ({name_placeholders})',
                        list(names),
                    )
                    total = int(cursor.fetchone()[0] or 0)
                    if total:
                        counts['learners'] = total
        except Exception:
            logger.debug('Could not count learners for programme %s.', identifier, exc_info=True)
    return counts


def programme_dependency_report(identifier, programme=None, config=None):
    counts = programme_dependency_counts(identifier, config)
    total = sum(parse_int(value, 0) for value in counts.values())
    return {
        'blocked': total > 0,
        'counts': counts,
        'total': total,
        'programme': {
            'id': clean_str(identifier),
            'sourceId': clean_str((programme or {}).get('sourceId') or programme_config_identity(config) or identifier),
            'name': clean_str((programme or {}).get('name') or (config or {}).get('name')),
        },
        'cleanupStartStep': 'cohort',
        'message': (
            'This programme still has curriculum data attached. '
            'Open the programme wizard and remove modules, groups and cohorts before deleting the programme.'
        ),
    }


def archive_programme_config(identifier, config=None):
    """Soft-delete a programme by flagging curriculum.programmes.is_archived.

    Archiving hides the programme from the operational list while leaving every
    child row (cohorts, groups, modules) and every learner record intact. This
    is the default outcome for a delete request whenever the programme still
    has dependents — see programme_dependency_counts().

    Returns True when a row was flagged.
    """
    config = config or programme_config_by_identifier(identifier)
    if not config:
        return False
    try:
        key_column = programme_config_key_column()
        key_value = config.get(key_column)
        if key_value is None:
            return False
        updated = update_rows(
            'programmes',
            f'{quote_ident(key_column)} = %s',
            [key_value],
            soft_delete_payload('programmes', deleted_by='programme-archive'),
        )
        return bool(updated)
    except Exception:
        logger.warning('Could not archive programme %s.', identifier, exc_info=True)
        return False


def soft_delete_programme_authoring_structure(identifier, programme=None, config=None):
    """Archive a programme and mark its curriculum children as programme-deleted.

    This is intentionally a soft cascade: no learner, component, week, module,
    group or cohort content is removed. Operational reads already hide rows
    carrying is_programme_deleted, while the data remains inspectable in Neon.
    """
    config = config or programme_config_by_identifier(identifier)
    programme_id = clean_str(programme_config_identity(config) or identifier)
    programme_name = clean_str((programme or {}).get('name') or (config or {}).get('name'))
    candidates = {value for value in {
        programme_id,
        clean_str((programme or {}).get('sourceId')),
        clean_str((programme or {}).get('id')),
    } if value}
    result = {
        'programmeArchived': False,
        'cohorts': 0,
        'groups': 0,
        'modules': 0,
        'weeks': 0,
        'components': 0,
        'ksbMappings': 0,
    }
    if not candidates:
        return result

    try:
        ensure_program_config_archive_columns()
        if config:
            key_column = programme_config_key_column()
            key_value = config.get(key_column)
            if key_value is not None:
                result['programmeArchived'] = bool(update_rows(
                    'programmes',
                    f'{quote_ident(key_column)} = %s',
                    [key_value],
                    soft_delete_payload('programmes', deleted_by='programme-delete'),
                ))
    except Exception:
        logger.warning('Could not archive programme %s during soft delete.', identifier, exc_info=True)

    placeholders = ', '.join(['%s'] * len(candidates))
    params = list(candidates)
    try:
        result['cohorts'] = len(authoring_soft_delete(
            COHORT_AUTHORING_DETAILS_TABLE,
            f'programme_id in ({placeholders})',
            params,
            via_parent=programme_id,
            deleted_by='programme-delete',
        ))

        result['groups'] = len(authoring_soft_delete(
            GROUPS_TABLE,
            f'programme_id in ({placeholders})',
            params,
            via_parent=programme_id,
            deleted_by='programme-delete',
        ))

        result['modules'] = len(authoring_soft_delete(
            AUTHORING_MODULES_TABLE,
            f'''
            programme_id in ({placeholders})
            or group_id in (
                select group_id
                  from {authoring_table_name(GROUPS_TABLE)}
                 where programme_id in ({placeholders})
            )
            ''',
            [*params, *params],
            via_parent=programme_id,
            deleted_by='programme-delete',
        ))

        scoped_modules_sql = f'''
            select module_catalogue_id
              from {authoring_table_name(AUTHORING_MODULES_TABLE)}
             where programme_id in ({placeholders})
                or group_id in (
                    select group_id
                      from {authoring_table_name(GROUPS_TABLE)}
                     where programme_id in ({placeholders})
                )
        '''
        result['weeks'] = len(authoring_soft_delete(
            AUTHORING_WEEKS_TABLE,
            f'''
            module_catalogue_id in (
                {scoped_modules_sql}
            )
            ''',
            [*params, *params],
            via_parent=programme_id,
            deleted_by='programme-delete',
        ))

        scoped_weeks_sql = f'''
            select id
              from {authoring_table_name(AUTHORING_WEEKS_TABLE)}
             where module_catalogue_id in ({scoped_modules_sql})
        '''
        result['components'] = len(authoring_soft_delete(
            AUTHORING_COMPONENTS_TABLE,
            f'''
            module_catalogue_id in (
                {scoped_modules_sql}
            )
            or week_id in (
                {scoped_weeks_sql}
            )
            ''',
            [*params, *params, *params, *params],
            via_parent=programme_id,
            deleted_by='programme-delete',
        ))

        scoped_components_sql = f'''
            select id
              from {authoring_table_name(AUTHORING_COMPONENTS_TABLE)}
             where module_catalogue_id in ({scoped_modules_sql})
                or week_id in ({scoped_weeks_sql})
        '''
        result['ksbMappings'] = len(authoring_soft_delete(
            AUTHORING_KSB_MAPPINGS_TABLE,
            f'''
            module_catalogue_id in (
                {scoped_modules_sql}
            )
            or week_id in (
                {scoped_weeks_sql}
            )
            or component_id in (
                {scoped_components_sql}
            )
            ''',
            [*params, *params, *params, *params, *params, *params, *params, *params],
            via_parent=programme_id,
            deleted_by='programme-delete',
        ))
    except Exception:
        logger.warning('Could not soft-delete programme children for %s (%s).', identifier, programme_name, exc_info=True)
        raise
    invalidate_curriculum_cache()
    return result


# The soft-delete bookkeeping columns a restore has to blank. filtered_payload
# drops None unless a column is named here, so leaving them out would silently
# keep deleted_at set and the row would stay invisible.
RESTORE_NULLABLE_COLUMNS = ('deleted_at', 'deleted_by', 'deleted_via_parent')


def restore_rows_via_parent(table, parent_id):
    """Undo one soft-delete cascade, and only that one.

    Rows are matched on ``deleted_via_parent``, the marker
    ``soft_delete_programme_authoring_structure`` stamps on everything it takes
    down. A cohort archived on its own carries an empty marker, so restoring the
    programme leaves it archived rather than silently reviving it.
    """
    if not has_column(table, 'deleted_via_parent'):
        return []
    payload = restore_soft_delete_payload(table)
    if has_column(table, 'is_archived'):
        payload['is_archived'] = False
    if has_column(table, 'status') and table in {'cohorts'}:
        payload['status'] = 'active'
    return update_rows(
        table,
        f'{quote_ident("deleted_via_parent")} = %s',
        [parent_id],
        payload,
        allow_null_columns=RESTORE_NULLABLE_COLUMNS,
    )


def restore_programme_authoring_structure(identifier, programme=None, config=None):
    """Bring an archived programme and its cascade-archived children back.

    The mirror image of ``soft_delete_programme_authoring_structure``: the
    programme row loses its archive flags and every child that went down *with
    this programme* is un-marked. Children archived independently keep their own
    state, so restoring is not a way to resurrect unrelated deletions.
    """
    config = config or programme_config_by_identifier(identifier)
    programme_id = clean_str(programme_config_identity(config) or identifier)
    result = {
        'programmeRestored': False,
        'cohorts': 0,
        'groups': 0,
        'modules': 0,
        'weeks': 0,
        'components': 0,
        'ksbMappings': 0,
    }
    if not programme_id:
        return result

    try:
        ensure_program_config_archive_columns()
        if config:
            key_column = programme_config_key_column()
            key_value = config.get(key_column)
            if key_value is not None:
                payload = restore_payload('programmes', config.get('notes'))
                payload.update(restore_soft_delete_payload('programmes'))
                result['programmeRestored'] = bool(update_rows(
                    'programmes',
                    f'{quote_ident(key_column)} = %s',
                    [key_value],
                    payload,
                    allow_null_columns=RESTORE_NULLABLE_COLUMNS,
                ))
    except Exception:
        logger.warning('Could not restore programme %s.', identifier, exc_info=True)
        raise

    try:
        ensure_module_authoring_tables()
        for key, table in (
            ('cohorts', COHORT_AUTHORING_DETAILS_TABLE),
            ('groups', GROUPS_TABLE),
            ('modules', AUTHORING_MODULES_TABLE),
            ('weeks', AUTHORING_WEEKS_TABLE),
            ('components', AUTHORING_COMPONENTS_TABLE),
            ('ksbMappings', AUTHORING_KSB_MAPPINGS_TABLE),
        ):
            result[key] = len(restore_rows_via_parent(table, programme_id))
    except Exception:
        logger.warning('Could not restore programme children for %s.', identifier, exc_info=True)
        raise
    invalidate_curriculum_cache()
    return result


# Learner-side tables holding ON DELETE RESTRICT foreign keys into the curriculum
# content a programme owns. Postgres itself refuses to remove content a learner
# has already been given, so a permanent delete reports these as blockers instead
# of quietly deleting somebody's delivery record.
PROGRAMME_PERMANENT_DELETE_LEARNER_LINKS = (
    ('learner_training_plan_modules', 'curriculum_module_id', 'moduleIds'),
    ('learner_training_plan_weeks', 'curriculum_week_id', 'weekIds'),
    ('learner_training_plan_components', 'curriculum_component_id', 'componentIds'),
)


def curriculum_in_clause(column, values):
    """``column in (...)`` for a list of ids, or an empty clause when there are none."""
    values = [value for value in (values or []) if clean_str(value)]
    if not values:
        return '', []
    placeholders = ', '.join(['%s'] * len(values))
    return f'{quote_ident(column)} in ({placeholders})', values


def curriculum_where_any(clauses):
    """OR the non-empty clauses together, or return no SQL at all.

    An empty id list must never widen into ``where true``: on a delete that is
    the whole table. Callers therefore skip the statement entirely when this
    returns an empty ``where`` rather than falling back to a default predicate.
    """
    usable = [(sql, params) for sql, params in clauses if sql and params]
    if not usable:
        return '', []
    return (
        ' or '.join(sql for sql, _ in usable),
        [value for _, values in usable for value in values],
    )


def curriculum_ids_matching(table, column, clauses):
    where_sql, params = curriculum_where_any(clauses)
    if not where_sql or not table_exists(table):
        return []
    rows = fetch_all(
        f'select distinct {quote_ident(column)} as value from {table_name(table)} where {where_sql}',
        params,
    )
    return [clean_str(row.get('value')) for row in rows if clean_str(row.get('value'))]


def programme_identifier_candidates(identifier, programme=None, config=None):
    """Every id a child row may legitimately carry for this programme."""
    values = {
        clean_str(identifier),
        clean_str(programme_config_identity(config)),
        clean_str((programme or {}).get('sourceId')),
        clean_str((programme or {}).get('id')),
    }
    return sorted(value for value in values if value)


def programme_permanent_delete_blockers(child_ids):
    """Learner rows the database itself refuses to orphan.

    ``Learner.learner_training_plan_{modules,weeks,components}`` reference
    curriculum modules, weeks and components with ON DELETE RESTRICT. A learner's
    training plan is their delivery record, so content they hold is not something
    a programme delete may remove; it is reported and the delete is refused.
    """
    blockers = {}
    if connection.vendor != 'postgresql':
        return blockers
    for table, column, key in PROGRAMME_PERMANENT_DELETE_LEARNER_LINKS:
        values = [value for value in (child_ids.get(key) or []) if clean_str(value)]
        if not values:
            continue
        try:
            with connection.cursor() as cursor:
                cursor.execute('select to_regclass(%s)', [f'"Learner"."{table}"'])
                if not cursor.fetchone()[0]:
                    continue
                placeholders = ', '.join(['%s'] * len(values))
                cursor.execute(
                    f'select count(*) from "Learner".{quote_ident(table)} '
                    f'where {quote_ident(column)} in ({placeholders})',
                    values,
                )
                total = int(cursor.fetchone()[0] or 0)
        except Exception:
            # A count we cannot run is not a green light: the RESTRICT foreign key
            # still refuses the delete, and the caller turns that into the same 409.
            logger.warning('Could not count %s rows for a permanent programme delete.', table, exc_info=True)
            continue
        if total:
            blockers[table] = total
    return blockers


def programme_permanent_delete_plan(identifier, programme=None, config=None):
    """Read-only plan for a permanent delete: what would go, and what blocks it.

    Children are resolved through their own parents as well as through
    ``programme_id``. A group whose programme_id was never stamped, or a module
    attached only to a group, still belongs to the programme and must not survive
    it - those are precisely the orphans migration 0038 was added to stop.
    """
    candidates = programme_identifier_candidates(identifier, programme, config)
    plan = {
        'candidates': candidates,
        'childIds': {
            'cohortIds': [],
            'groupIds': [],
            'moduleIds': [],
            'weekIds': [],
            'componentIds': [],
            'weekTemplateIds': [],
        },
        'blockers': {},
        'learners': 0,
    }
    if not candidates:
        return plan

    programme_clause = curriculum_in_clause('programme_id', candidates)
    child = plan['childIds']
    child['cohortIds'] = curriculum_ids_matching(
        COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id', [programme_clause],
    )
    child['groupIds'] = curriculum_ids_matching(GROUPS_TABLE, 'group_id', [
        programme_clause,
        curriculum_in_clause('cohort_id', child['cohortIds']),
    ])
    child['moduleIds'] = curriculum_ids_matching(AUTHORING_MODULES_TABLE, 'module_catalogue_id', [
        programme_clause,
        curriculum_in_clause('cohort_id', child['cohortIds']),
        curriculum_in_clause('group_id', child['groupIds']),
    ])
    child['weekIds'] = curriculum_ids_matching(AUTHORING_WEEKS_TABLE, 'id', [
        curriculum_in_clause('module_catalogue_id', child['moduleIds']),
    ])
    child['componentIds'] = curriculum_ids_matching(AUTHORING_COMPONENTS_TABLE, 'id', [
        curriculum_in_clause('module_catalogue_id', child['moduleIds']),
        curriculum_in_clause('week_id', child['weekIds']),
    ])
    child['weekTemplateIds'] = curriculum_ids_matching(WEEK_TEMPLATES_TABLE, 'id', [
        programme_clause,
        curriculum_in_clause('group_id', child['groupIds']),
        curriculum_in_clause('module_catalogue_id', child['moduleIds']),
    ])
    plan['origins'] = programme_permanent_delete_origins(child)
    plan['blockers'] = programme_permanent_delete_blockers(child)
    plan['learners'] = parse_int(programme_dependency_counts(identifier, config).get('learners'), 0)
    return plan


def programme_permanent_delete_origins(child_ids):
    """Human-readable labels for the parents that are about to be removed.

    Content detached into the library keeps a denormalised note of where it came
    from, and this is the only moment that note can be taken: once the module
    and week rows are gone their titles are unrecoverable.
    """
    origins = {'modules': {}, 'weeks': {}}
    module_ids = child_ids.get('moduleIds') or []
    week_ids = child_ids.get('weekIds') or []
    if module_ids and table_exists(AUTHORING_MODULES_TABLE):
        where_sql, params = curriculum_where_any([
            curriculum_in_clause('module_catalogue_id', module_ids),
        ])
        if where_sql:
            for row in fetch_all(
                f'select module_catalogue_id, title from {table_name(AUTHORING_MODULES_TABLE)} where {where_sql}',
                params,
            ):
                origins['modules'][clean_str(row.get('module_catalogue_id'))] = clean_str(row.get('title'))
    if week_ids and table_exists(AUTHORING_WEEKS_TABLE):
        where_sql, params = curriculum_where_any([curriculum_in_clause('id', week_ids)])
        if where_sql:
            for row in fetch_all(
                f'select id, week_number, title from {table_name(AUTHORING_WEEKS_TABLE)} where {where_sql}',
                params,
            ):
                origins['weeks'][clean_str(row.get('id'))] = component_week_label(row)
    return origins


def detach_programme_content_to_library(plan, removed):
    """Move authored content out of a dying programme instead of destroying it.

    Weeks and components are the reusable output of Curriculum Studio and an
    author may well want them again in a different module, so a permanent
    programme delete detaches them into the library rather than deleting them.
    They keep a denormalised note of where they came from, taken from
    ``plan['origins']`` while the parent rows still exist.

    Quizzes are detached too, by clearing their programme and week. They are
    already standalone rows carrying learner attempts, and their questions and
    answers hang off them by ``ON DELETE CASCADE`` - a cascade that from here on
    simply never fires for a programme delete.
    """
    child = plan.get('childIds') or {}
    origins = plan.get('origins') or {}
    module_titles = origins.get('modules') or {}
    week_labels = origins.get('weeks') or {}
    week_ids = child.get('weekIds') or []
    component_ids = set(child.get('componentIds') or [])

    def count(table, rows):
        if rows:
            removed[table] = removed.get(table, 0) + len(rows)

    # Components carry their own week, so detach one week at a time to stamp the
    # right origin on each. A programme has tens of weeks, not thousands.
    detached_component_ids = set()
    if component_ids and table_exists(AUTHORING_COMPONENTS_TABLE):
        for week_id in week_ids:
            rows = authoring_fetch_all(
                AUTHORING_COMPONENTS_TABLE, 'week_id = %s', [week_id],
            )
            matching = [row for row in rows if clean_str(row.get('id')) in component_ids]
            if not matching:
                continue
            ids = [clean_str(row.get('id')) for row in matching]
            # Every component in a week shares its module, so the first matching
            # row settles it - but read it from a row we are actually detaching.
            module_id = clean_str(matching[0].get('module_catalogue_id'))
            placeholders = ', '.join(['%s'] * len(ids))
            count(AUTHORING_COMPONENTS_TABLE, detach_rows_to_library(
                AUTHORING_COMPONENTS_TABLE,
                f'id in ({placeholders})',
                ids,
                origin_module_id=module_id,
                origin_module_title=module_titles.get(module_id, ''),
                origin_week_id=week_id,
                origin_week_label=week_labels.get(week_id, ''),
            ))
            detached_component_ids.update(ids)
        # A component attached to the module but to no surviving week still has
        # to come along, or it would be left pointing at a module that is gone.
        # Grouped by module so these keep a provenance label too.
        stragglers = component_ids - detached_component_ids
        if stragglers:
            by_module = defaultdict(list)
            where_sql, params = curriculum_where_any([
                curriculum_in_clause('id', sorted(stragglers)),
            ])
            if where_sql:
                for row in fetch_all(
                    f'select id, module_catalogue_id from {table_name(AUTHORING_COMPONENTS_TABLE)} where {where_sql}',
                    params,
                ):
                    by_module[clean_str(row.get('module_catalogue_id'))].append(clean_str(row.get('id')))
            for module_id, ids in by_module.items():
                placeholders = ', '.join(['%s'] * len(ids))
                count(AUTHORING_COMPONENTS_TABLE, detach_rows_to_library(
                    AUTHORING_COMPONENTS_TABLE,
                    f'id in ({placeholders})',
                    ids,
                    origin_module_id=module_id,
                    origin_module_title=module_titles.get(module_id, ''),
                ))

    # Weeks, grouped by the module that is going away.
    if week_ids and table_exists(AUTHORING_WEEKS_TABLE):
        weeks_by_module = defaultdict(list)
        where_sql, params = curriculum_where_any([curriculum_in_clause('id', week_ids)])
        if where_sql:
            for row in fetch_all(
                f'select id, module_catalogue_id from {table_name(AUTHORING_WEEKS_TABLE)} where {where_sql}',
                params,
            ):
                weeks_by_module[clean_str(row.get('module_catalogue_id'))].append(clean_str(row.get('id')))
        for module_id, ids in weeks_by_module.items():
            placeholders = ', '.join(['%s'] * len(ids))
            count(AUTHORING_WEEKS_TABLE, detach_rows_to_library(
                AUTHORING_WEEKS_TABLE,
                f'id in ({placeholders})',
                ids,
                origin_module_id=module_id,
                origin_module_title=module_titles.get(module_id, ''),
            ))

    # Quizzes: unhook from the programme and week, keep the quiz.
    if table_exists('quizzes'):
        clauses = [curriculum_in_clause('programme_id', plan.get('candidates') or [])]
        if week_ids:
            clauses.append(curriculum_in_clause('week_id', week_ids))
        where_sql, params = curriculum_where_any(clauses)
        if where_sql:
            updates = {}
            if has_column('quizzes', 'week_id'):
                updates['week_id'] = DETACHED_PARENT_SENTINEL
            if has_column('quizzes', 'programme_id'):
                updates['programme_id'] = DETACHED_PARENT_SENTINEL
            if updates:
                count('quizzes', update_rows('quizzes', where_sql, params, updates))

    # Week templates are reusable by definition; unhook rather than delete.
    template_ids = child.get('weekTemplateIds') or []
    if template_ids and table_exists(WEEK_TEMPLATES_TABLE):
        where_sql, params = curriculum_where_any([curriculum_in_clause('id', template_ids)])
        if where_sql:
            updates = {'updated_at': datetime.utcnow()}
            for column in ('programme_id', 'programme_name', 'group_id', 'group_name', 'module_catalogue_id'):
                if has_column(WEEK_TEMPLATES_TABLE, column):
                    updates[column] = DETACHED_PARENT_SENTINEL
            count(WEEK_TEMPLATES_TABLE, update_rows(WEEK_TEMPLATES_TABLE, where_sql, params, updates))


def permanently_delete_programme_structure(plan):
    """Delete an archived programme, and detach the content authored under it.

    The order is dictated by the foreign keys migration 0038 added (children
    first, ON DELETE RESTRICT). That ordering is exactly what a hand-written
    ``delete from curriculum.programmes`` cannot supply, which is why Postgres
    answers it with ``cohorts_programme_id_fkey``.

    Authored content is *not* deleted. Weeks, components, quizzes and week
    templates are detached into the reuse library by
    ``detach_programme_content_to_library``; the delivery scaffolding around them
    - the programme, cohorts, groups, modules, live sessions and link rows - is
    what actually goes. Deleting a live session still takes its occurrences,
    attendance, artifacts and recording events with it by cascade.

    The link tables are cleared explicitly first, because a link may point at
    this programme's module from a quiz that belongs to another programme.

    ``ksb_mappings`` is still wiped, and that loses nothing: since 0042 a
    component owns its mappings in its own ``ksb_mappings`` JSONB column and
    that table is a projection of it (``component_ksb_mappings_from_row``
    prefers the JSONB). Detached components keep their KSBs.

    Learner accounts, progress and enrolment rows are never touched. The
    training-plan tables that reference this content are RESTRICT-guarded and
    surface through ``plan['blockers']`` before anything is deleted.
    """
    candidates = plan.get('candidates') or []
    child = plan.get('childIds') or {}
    removed = {}
    if not candidates:
        return removed

    def wipe(table, clauses):
        where_sql, params = curriculum_where_any(clauses)
        if not where_sql or not table_exists(table):
            return
        rows = delete_rows(table, where_sql, params)
        if rows:
            removed[table] = len(rows)

    programme_clause = curriculum_in_clause('programme_id', candidates)
    module_clause = curriculum_in_clause('module_catalogue_id', child.get('moduleIds'))
    week_clause = curriculum_in_clause('week_id', child.get('weekIds'))
    component_clause = curriculum_in_clause('component_id', child.get('componentIds'))

    # Detach first, while the module and week rows are still here to be read.
    detach_programme_content_to_library(plan, removed)

    wipe(AUTHORING_KSB_MAPPINGS_TABLE, [module_clause, week_clause, component_clause])
    wipe('quiz_component_links', [component_clause])
    wipe('quiz_course_links', [module_clause, week_clause])
    wipe('tutor_module_notifications', [module_clause])
    wipe('module_completion_criteria', [module_clause])
    wipe('module_details', [module_clause])
    wipe(LIVE_SESSIONS_TABLE, [module_clause])
    wipe('free_programme_components', [programme_clause])
    wipe('free_programme_modules', [programme_clause])
    wipe(AUTHORING_MODULES_TABLE, [
        curriculum_in_clause('module_catalogue_id', child.get('moduleIds')),
    ])
    wipe(GROUPS_TABLE, [curriculum_in_clause('group_id', child.get('groupIds'))])
    wipe(COHORT_AUTHORING_DETAILS_TABLE, [
        curriculum_in_clause('cohort_id', child.get('cohortIds')),
    ])
    wipe('programmes', [curriculum_in_clause(programme_config_key_column(), candidates)])

    invalidate_curriculum_cache()
    return removed


def request_wants_permanent_programme_delete(request):
    """A permanent delete is opt-in per request; the default DELETE still archives."""
    return (
        truthy(request.GET.get('permanent'))
        or truthy(request.GET.get('hard'))
        or clean_str(request.GET.get('mode')).lower() in {'permanent', 'hard'}
    )


def permanent_programme_delete_response(identifier, programme=None, config=None):
    """HTTP outcome of a permanent programme delete.

    Archived-only by design: ``is_archived`` is the switch that turns an
    irreversible delete on. A live programme is refused with 409 so the caller
    archives it first, which is what the plain DELETE does.
    """
    archived = is_archived_program_config(config) or programme_status_is_archived(
        (programme or {}).get('status')
    )
    if not archived:
        return json_error(
            'Archive the programme before deleting it permanently.',
            status=409,
            reason='programme-not-archived',
            deleted=False,
            permanent=False,
            id=clean_str(identifier),
        )

    plan = programme_permanent_delete_plan(identifier, programme, config)
    if plan['blockers']:
        return json_error(
            'Learner training plans still reference this curriculum, so the programme '
            'cannot be deleted permanently.',
            status=409,
            reason='programme-has-learner-delivery',
            deleted=False,
            permanent=False,
            id=clean_str(identifier),
            blockers=plan['blockers'],
        )

    try:
        with transaction.atomic():
            removed = permanently_delete_programme_structure(plan)
    except (IntegrityError, DatabaseError) as exc:
        logger.warning('Permanent delete of programme %s was refused: %s', identifier, exc)
        return json_error(
            'The database refused the permanent delete because other rows still '
            'reference this programme.',
            status=409,
            reason='programme-delete-restricted',
            deleted=False,
            permanent=False,
            id=clean_str(identifier),
            detail=clean_str(str(exc)),
        )

    return JsonResponse({
        'deleted': True,
        'permanent': True,
        'archived': False,
        'id': clean_str(identifier),
        'removed': removed,
        'learners': plan['learners'],
        'message': 'Programme and every curriculum row beneath it were deleted permanently.',
    })


def curriculum_visibility(request):
    if truthy(request.GET.get('include_archived')):
        return 'all'
    visibility = str(request.GET.get('visibility') or 'operational').strip().lower()
    return 'all' if visibility == 'all' else 'operational'


def title_case_status(is_archived, start_value, end_value):
    if is_archived:
        return 'archived'

    today = date.today()
    start = parse_date(start_value)
    end = parse_date(end_value)
    if start and start > today:
        return 'planned'
    if end and end < today:
        return 'completed'
    return 'active'


def delivery_status_for_training_row(row):
    row = row or {}
    if '_meta' not in row:
        row = {**row, '_meta': extract_notes_meta(row.get('notes'))}
    if not is_operational_training_row(row):
        return 'archived'

    today = date.today()
    start = parse_date(row.get('start_date') or row.get('Starting_date_lable'))
    end = parse_date(row.get('end_date'))
    if start and today < start:
        return 'not_started'
    if start and end:
        if start <= today <= end:
            return 'active'
        if today > end:
            return 'completed'
    return 'unknown'


def extract_notes_meta(notes):
    meta = {}
    for line in str(notes or '').splitlines():
        if not line.startswith('__') or ':' not in line:
            continue
        key, value = line.split(':', 1)
        meta[key.strip('_')] = value.strip()
    return meta


def parse_notes_id_list(value):
    if isinstance(value, (list, tuple, set)):
        tokens = value
    else:
        tokens = re.split(r'[|,]+', str(value or ''))
    return [clean_str(token) for token in tokens if clean_str(token)]


def replace_visible_notes_preserving_meta(existing_notes, visible_notes):
    hidden_lines = [line for line in str(existing_notes or '').splitlines() if line.strip().startswith('__')]
    visible_lines = [line for line in str(visible_notes or '').splitlines() if not line.strip().startswith('__')]
    return '\n'.join([*visible_lines, *hidden_lines]).strip()


def visible_notes(notes):
    return '\n'.join(line for line in str(notes or '').splitlines() if not line.strip().startswith('__')).strip()


def codes_from_session_ksb(value):
    entries = parse_json_value(value, [])
    codes = set()
    if not isinstance(entries, list):
        return codes

    for entry in entries:
        if not isinstance(entry, dict):
            continue
        for key in ('knowledgeCodes', 'skillCodes', 'behaviourCodes'):
            codes.update(str(code) for code in entry.get(key, []) if code)
    return codes


def ksb_type_label(type_code):
    return {
        'K': 'Knowledge',
        'S': 'Skill',
        'B': 'Behaviour',
    }.get(str(type_code).upper(), 'Knowledge')


def normalise_ksb_type(value):
    raw = str(value or '').strip().upper()
    if raw in {'K', 'KNOWLEDGE'}:
        return 'K'
    if raw in {'S', 'SKILL', 'SKILLS'}:
        return 'S'
    if raw in {'B', 'BEHAVIOUR', 'BEHAVIOURS', 'BEHAVIOR', 'BEHAVIORS'}:
        return 'B'
    return 'K'


def normalise_ksb_code(value, type_code=''):
    code = str(value or '').strip().upper()
    type_code = normalise_ksb_type(type_code)
    if code.startswith(type_code):
        code = code[1:]
    return re.sub(r'[^0-9.]', '', code)


def full_ksb_code(item):
    type_code = normalise_ksb_type(item.get('type'))
    code = normalise_ksb_code(item.get('code') or item.get('full_code'), type_code)
    return f'{type_code}{code}' if code else ''


def infer_level(name):
    match = re.search(r'\bL(?:evel\s*)?(\d)\b|lv(?:l)?\s*(\d)|level\s*(\d)', str(name), re.I)
    if not match:
        return ''
    level = next(group for group in match.groups() if group)
    return f'L{level}'


def unique(values):
    seen = set()
    result = []
    for value in values:
        if value in (None, '') or value in seen:
            continue
        seen.add(value)
        result.append(value)
    return result


def get_module_session_names(module_row):
    json_names = parse_json_value(module_row.get('session_names_json'), None)
    if isinstance(json_names, list):
        names = [str(name).strip() for name in json_names if str(name).strip()]
        if names:
            return names

    names = []
    for index in range(1, 31):
        value = module_row.get(f'session_name_{index}')
        if value:
            names.append(str(value).strip())
    return names


def get_ksb_profile_for_program(program_name, ksb_profiles):
    program_norm = normalise(program_name)
    if not program_norm:
        return None
    for profile in ksb_profiles:
        candidates = [
            profile.get('name'),
            *ksb_profile_context_ids(profile, 'programme_ids'),
        ]
        for candidate in candidates:
            candidate_norm = normalise(candidate)
            if candidate_norm == program_norm:
                return profile
    return None


def ksb_profile_required_codes(profile):
    if not profile:
        return []
    ksb_items = parse_json_value(profile.get('ksb_items'), [])
    if isinstance(ksb_items, list) and ksb_items:
        return unique([
            coverage_normalise_code(full_ksb_code(item))
            for item in ksb_items
            if isinstance(item, dict)
        ])
    return unique([
        coverage_normalise_code(code)
        for code in [
            *parse_json_value(profile.get('knowledge_codes'), []),
            *parse_json_value(profile.get('skill_codes'), []),
            *parse_json_value(profile.get('behaviour_codes'), []),
        ]
    ])


def ksb_profile_source_id(profile):
    public_id = clean_str((profile or {}).get('id'))
    if public_id.startswith('KSBP-'):
        return public_id
    return clean_str((profile or {}).get('ksb_profile_id')) or unique_ksb_profile_id((profile or {}).get('name') or '')


def normalise_ksb_profile_source_value(value):
    source = clean_str(value)
    if ':' not in source:
        return source
    prefix, source_id = source.split(':', 1)
    if prefix.lower() in {'profile', 'framework'}:
        return clean_str(source_id)
    return source


def ksb_profile_context_ids(profile, key, primary_value=''):
    values = parse_json_value((profile or {}).get(key), [])
    if not isinstance(values, list):
        values = []
    return unique([clean_str(primary_value), *[clean_str(value) for value in values]])


def payload_context_ids(payload, camel_key, snake_key, single_keys=()):
    values = payload.get(camel_key)
    if values is None:
        values = payload.get(snake_key)
    if not isinstance(values, list):
        values = []
    singles = [payload.get(key) for key in single_keys]
    return unique([*[clean_str(value) for value in values], *[clean_str(value) for value in singles]])


def unlink_programmes_from_other_ksb_profiles(active_profile_id, programme_values):
    targets = {normalise(value) for value in programme_values if normalise(value)}
    if not targets:
        return
    for row in get_ksb_profile_rows():
        row_id = clean_str(row.get('id'))
        if row_id == clean_str(active_profile_id):
            continue
        current_context = ksb_profile_context_ids(row, 'programme_ids')
        current_values = unique(current_context)
        if not any(normalise(value) in targets for value in current_values):
            continue
        next_context = [value for value in current_context if normalise(value) not in targets]
        update_rows('ksb_profiles', 'id = %s', [row_id], {
            'programme_ids': json.dumps(next_context),
            'updated_at': datetime.utcnow(),
        })


def cascade_ksb_profile_source_to_programme_modules(programme_values, source_id):
    return set_programme_modules_ksb_source(programme_values, source_id)


def set_programme_modules_ksb_source(programme_values, source_value):
    raw_targets = unique([clean_str(value) for value in programme_values if clean_str(value)])
    targets = {normalise(value) for value in raw_targets if normalise(value)}
    source_value = normalise_ksb_profile_source_value(source_value)
    if not raw_targets:
        return 0
    ensure_module_authoring_tables()
    if connection.vendor == 'postgresql':
        placeholders = ', '.join(['%s'] * len(raw_targets))
        params = [source_value, datetime.utcnow(), *raw_targets]
        with connection.cursor() as cursor:
            cursor.execute(
                f'''
                update {authoring_table_name(AUTHORING_MODULES_TABLE)}
                set ksb_profile_source_id = %s, updated_at = %s
                where programme_id in ({placeholders})
                   or programme_name in ({placeholders})
                ''',
                [*params, *raw_targets],
            )
            return cursor.rowcount
    updated = 0
    for module in authoring_fetch_all(AUTHORING_MODULES_TABLE):
        module_programme_values = [
            module.get('programme_id'),
            module.get('programme_name'),
        ]
        if not any(normalise(value) in targets for value in module_programme_values):
            continue
        module_id = clean_str(module.get('module_catalogue_id'))
        if not module_id:
            continue
        update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_id], {
            'ksb_profile_source_id': source_value,
            'updated_at': datetime.utcnow(),
        })
        updated += 1
    return updated


def program_config_by_id(program_configs):
    configs = {}
    configs_by_name = {}
    for config in program_configs:
        config_id = programme_config_id(config)
        if config_id:
            configs[config_id] = config
        if config.get('name'):
            name_key = normalise(config.get('name'))
            current = configs_by_name.get(name_key)
            if not current or program_config_preference(config) > program_config_preference(current):
                configs_by_name[name_key] = config
    configs.update(configs_by_name)
    return configs


def programme_config_id(config):
    return clean_str((config or {}).get('programme_id') or (config or {}).get('id') or (config or {}).get('program_id'))


def programme_config_key_column():
    for column in ('programme_id', 'id', 'program_id'):
        try:
            if has_column('programmes', column):
                return column
        except Exception:
            continue
    return 'programme_id'


def program_config_preference(config):
    if not config:
        return (-1, 0, 0)
    updated = config.get('updated_at') or config.get('created_at')
    try:
        if hasattr(updated, 'timestamp'):
            timestamp = updated.timestamp()
        else:
            updated_text = clean_str(updated)
            if updated_text.endswith('Z'):
                updated_text = f'{updated_text[:-1]}+00:00'
            timestamp = datetime.fromisoformat(updated_text).timestamp() if updated_text else 0
    except Exception:
        timestamp = 0
    return (
        0 if is_archived_program_config(config) else 1,
        timestamp,
        parse_int(config.get('id'), 0),
    )


def unique_program_configs_for_display(program_configs):
    active = []
    active_names = set()
    archived_by_name = {}
    archived_unnamed = []
    for config in program_configs:
        if not is_archived_program_config(config):
            active.append(config)
            active_name = normalise(config.get('name'))
            active_names.add(active_name)
            archived_by_name.pop(active_name, None)
            continue
        name_key = normalise(config.get('name'))
        if not name_key:
            archived_unnamed.append(config)
            continue
        if name_key in active_names:
            continue
        current = archived_by_name.get(name_key)
        if not current or program_config_preference(config) > program_config_preference(current):
            archived_by_name[name_key] = config
    return [*active, *archived_by_name.values(), *archived_unnamed]


def preferred_program_config_by_name(program_configs, name):
    name_key = normalise(name)
    if not name_key:
        return None
    matches = [config for config in program_configs if normalise(config.get('name')) == name_key]
    return max(matches, key=program_config_preference) if matches else None


def programme_config_for_programme(program_configs, programme):
    programme_ids = {
        clean_str(programme.get('id')),
        clean_str(programme.get('sourceId')),
    }
    programme_ids = {value for value in programme_ids if value}
    programme_name = normalise(programme.get('name'))
    for config in program_configs or []:
        if programme_config_identity(config) in programme_ids:
            return config
    if programme_name:
        return preferred_program_config_by_name(program_configs or [], programme.get('name'))
    return None


def programme_config_json_list(config, key):
    value = (config or {}).get(key)
    parsed = as_json_value(value, [])
    if isinstance(parsed, list):
        return parsed
    if isinstance(parsed, dict):
        return list(parsed.values())
    return []


def curriculum_item_richness(item):
    if not isinstance(item, dict):
        return 0
    week_structure = item.get('weekStructure') or item.get('week_structure') or []
    components = item.get('components') or []
    nested_components = sum(
        len(week.get('components') or [])
        for week in week_structure
        if isinstance(week, dict)
    ) if isinstance(week_structure, list) else 0
    groups = item.get('groups') or []
    modules = item.get('modules') or []
    return (
        len(week_structure) * 1000 if isinstance(week_structure, list) else 0
    ) + nested_components * 100 + (
        len(components) * 50 if isinstance(components, list) else 0
    ) + (
        len(groups) * 25 if isinstance(groups, list) else 0
    ) + (
        len(modules) * 10 if isinstance(modules, list) else 0
    ) + len(json.dumps(item, default=str))


def unique_curriculum_items(items, identity_fields):
    selected = {}
    order = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        key = next((clean_str(item.get(field)) for field in identity_fields if clean_str(item.get(field))), '')
        if not key:
            key = normalise(item.get('name') or item.get('title'))
        if not key:
            key = f'row:{len(order)}'
        if key not in selected:
            order.append(key)
            selected[key] = item
            continue
        current = selected[key]
        if curriculum_item_richness(item) >= curriculum_item_richness(current):
            selected[key] = {**current, **item}
    return [selected[key] for key in order]


def curriculum_module_from_authoring_payload(payload):
    if not isinstance(payload, dict):
        return {}
    catalogue_id = clean_str(
        payload.get('moduleCatalogueId')
        or payload.get('catalogueId')
        or payload.get('moduleId')
        or payload.get('structureId')
        or payload.get('module_catalogue_id')
    )
    week_structure = payload.get('weekStructure') or payload.get('week_structure') or []
    sessions_number = parse_int(payload.get('sessionsNumber') or payload.get('sessions_number'), len(week_structure))
    return {
        **payload,
        'id': catalogue_id or clean_str(payload.get('id')),
        'sourceId': catalogue_id or clean_str(payload.get('sourceId') or payload.get('id')),
        'moduleId': catalogue_id or clean_str(payload.get('moduleId')),
        'moduleCatalogueId': catalogue_id or clean_str(payload.get('moduleCatalogueId')),
        'catalogueId': catalogue_id or clean_str(payload.get('catalogueId')),
        'structureId': catalogue_id or clean_str(payload.get('structureId')),
        'name': payload.get('name') or payload.get('title') or payload.get('moduleName') or '',
        'programmeId': payload.get('programmeId') or payload.get('programme_id') or '',
        'programme': payload.get('programme') or payload.get('programmeName') or payload.get('programme_name') or '',
        'cohortId': payload.get('cohortId') or payload.get('cohort_id') or '',
        'cohort': payload.get('cohort') or payload.get('cohortName') or payload.get('cohort_name') or '',
        'groupId': payload.get('groupId') or payload.get('group_id') or '',
        'group': payload.get('group') or payload.get('groupName') or payload.get('group_name') or '',
        'notes': payload.get('notes') if payload.get('notes') is not None else payload.get('description') or '',
        'sessionsNumber': sessions_number,
        'weeks': parse_int(payload.get('weeks'), sessions_number),
        'weekStructure': week_structure,
    }


def programme_authoring_modules(programme, config=None):
    programme_ids = {
        clean_str(programme.get('id')),
        clean_str(programme.get('sourceId')),
        clean_str(programme_config_identity(config)),
    }
    programme_ids = {value for value in programme_ids if value}
    programme_names = {normalise(programme.get('name')), normalise((config or {}).get('name'))}
    programme_names = {value for value in programme_names if value}
    rows = []
    for row in safe_authoring_module_rows():
        if row_has_deleted_at(row) or programme_deleted_row(row):
            continue
        row_programme_id = clean_str(row.get('programme_id'))
        row_programme_name = normalise(row.get('programme_name'))
        if (row_programme_id and row_programme_id in programme_ids) or (row_programme_name and row_programme_name in programme_names):
            rows.append(row)
    modules = []
    for row in rows:
        module_id = clean_str(row.get('module_catalogue_id'))
        payload = get_authoring_structure_payload(module_id) if module_id else None
        if payload:
            modules.append(curriculum_module_from_authoring_payload(payload))
        else:
            modules.append(curriculum_module_from_authoring_payload({
                'moduleCatalogueId': module_id,
                'title': row.get('title') or '',
                'programmeId': row.get('programme_id') or '',
                'programmeName': row.get('programme_name') or '',
                'cohortId': row.get('cohort_id') or '',
                'cohort': row.get('cohort_name') or '',
                'groupId': row.get('group_id') or '',
                'group': row.get('group_name') or '',
                'sessionsNumber': row.get('sessions_number') or 0,
                'startDate': format_date(row.get('start_date')),
                'endDate': format_date(row.get('end_date')),
                'weekDays': row.get('session_week_day') or '',
                'startTime': row.get('session_start_time') or '',
                'endTime': row.get('session_end_time') or '',
                'tutor': row.get('tutor_name') or '',
                'description': row.get('description') or '',
            }))
    return modules


def programme_config_modules(config):
    modules = []
    for item in programme_config_json_list(config, 'modules'):
        if isinstance(item, dict):
            modules.append(curriculum_module_from_authoring_payload(item))
            continue
        module_id = clean_str(item)
        payload = get_authoring_structure_payload(module_id) if module_id else None
        if payload:
            modules.append(curriculum_module_from_authoring_payload(payload))
    return modules


def normalise_programme_config_cohort(item, programme):
    if not isinstance(item, dict):
        return {}
    cohort_id = clean_str(item.get('id') or item.get('cohortId') or item.get('cohort_id'))
    return {
        **item,
        'id': cohort_id,
        'name': item.get('name') or item.get('cohortName') or item.get('cohort_name') or cohort_id,
        'programmeId': item.get('programmeId') or item.get('programme_id') or programme.get('sourceId') or programme.get('id'),
        'programme': item.get('programme') or item.get('programmeName') or item.get('programme_name') or programme.get('name'),
    }


def normalise_programme_config_group(item, programme):
    if not isinstance(item, dict):
        return {}
    group_id = clean_str(item.get('id') or item.get('groupId') or item.get('group_id'))
    return {
        **item,
        'id': group_id,
        'name': item.get('name') or item.get('groupName') or item.get('group_name') or group_id,
        'cohortId': item.get('cohortId') or item.get('cohort_id') or '',
        'cohort': item.get('cohort') or item.get('cohortName') or item.get('cohort_name') or '',
        'programmeId': item.get('programmeId') or item.get('programme_id') or programme.get('sourceId') or programme.get('id'),
        'programme': item.get('programme') or item.get('programmeName') or item.get('programme_name') or programme.get('name'),
        'moduleIds': item.get('moduleIds') or item.get('module_ids') or [],
        'modules': item.get('modules') or item.get('moduleNames') or item.get('module_names') or [],
    }


def programme_identity(row, program_configs_by_id):
    meta = row.get('_meta', {})
    program_id = meta.get('program_id')
    row_name = row.get('Program') or 'Unassigned Programme'
    if program_id:
        config = program_configs_by_id.get(str(program_id))
        name = (config or {}).get('name') or row_name
        canonical_config = config or program_configs_by_id.get(normalise(name))
        canonical_source_id = programme_config_identity(canonical_config) or program_id
        return {
            'key': f'id:{clean_str(canonical_source_id)}' if clean_str(canonical_source_id) else f'name:{normalise(name)}',
            'sourceId': canonical_source_id,
            'name': (canonical_config or {}).get('name') or name,
            'config': canonical_config,
        }

    name = row_name
    config = program_configs_by_id.get(normalise(name))
    return {
        'key': f'name:{normalise(config.get("name") if config else name)}',
        'sourceId': config.get('program_id') if config and config.get('program_id') else slugify(name),
        'name': config.get('name') if config and config.get('name') else name,
        'config': config,
    }


def canonical_programme_name(row, program_configs_by_id):
    return programme_identity(row, program_configs_by_id)['name']


def actual_cohort_identity(row, programme_name):
    meta = row.get('_meta', {})
    cohort_name = clean_str(row.get('Cohort_name'))
    if not cohort_name:
        return None
    return {
        'id': clean_str(meta.get('cohort_id')) or f'{slugify(programme_name)}-{slugify(cohort_name)}',
        'name': cohort_name,
    }


def actual_group_identity(row, cohort_id):
    meta = row.get('_meta', {})
    group_name = clean_str(row.get('group_name') or meta.get('group_name'))
    if not group_name:
        return None
    return {
        'id': clean_str(meta.get('group_id')) or f'{cohort_id}-{slugify(group_name)}',
        'name': group_name,
    }


def is_actual_delivery_row(row, program_configs_by_id):
    if not clean_str(row.get('module_name')):
        return False
    identity = programme_identity(row, program_configs_by_id)
    cohort = actual_cohort_identity(row, identity['name'])
    if not cohort:
        return False
    return bool(actual_group_identity(row, cohort['id']))


def authoring_modules_as_training_rows(*, ensure_tables=True):
    try:
        module_rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, ensure_tables=ensure_tables)
        group_rows = {clean_str(row.get('group_id')): row for row in authoring_fetch_all(GROUPS_TABLE, ensure_tables=ensure_tables)}
        cohort_rows = {clean_str(row.get('cohort_id')): row for row in authoring_fetch_all(COHORT_AUTHORING_DETAILS_TABLE, ensure_tables=ensure_tables)}
    except (Exception, AssertionError):
        logger.debug('Could not build fallback training rows from authoring tables.', exc_info=True)
        return []

    rows = []
    for module in module_rows:
        module_id = clean_str(module.get('module_catalogue_id'))
        group_id = clean_str(module.get('group_id'))
        cohort_id = clean_str(module.get('cohort_id'))
        if not group_id or not cohort_id:
            continue
        group = group_rows.get(group_id) or {}
        cohort = cohort_rows.get(cohort_id) or {}
        is_programme_deleted = programme_deleted_row(module) or programme_deleted_row(group)
        programme_id = clean_str(group.get('programme_id') or cohort.get('programme_id') or module.get('programme_id'))
        programme_name = clean_str(group.get('programme_name') or cohort.get('programme_name') or module.get('programme_name') or 'Unassigned programme')
        cohort_name = clean_str(group.get('cohort_name') or cohort.get('cohort_name') or module.get('cohort_name') or 'Unassigned cohort')
        group_name = clean_str(group.get('group_name') or module.get('group_name') or 'Unassigned group')
        meta = {
            'program_id': programme_id,
            'cohort_id': cohort_id,
            'group_id': group_id,
            'group_name': group_name,
            TRAINING_MODULE_CATALOGUE_COLUMN: module_id,
        }
        if is_programme_deleted:
            meta['is_programme_deleted'] = 'true'
        rows.append({
            'id': module_id,
            'Program': programme_name,
            'Cohort_name': cohort_name,
            'group_name': group_name,
            'module_name': module.get('title') or f'Module {module_id}',
            'status': clean_str(module.get('status') or 'draft').lower(),
            'sessions_number': module.get('sessions_number') or 0,
            'Tutor_name': module.get('tutor_name') or '',
            'coach_name': group.get('coach_name') or '',
            'Starting_date_lable': cohort.get('start_date') or module.get('start_date'),
            'start_date': module.get('start_date') or cohort.get('start_date'),
            'end_date': module.get('end_date') or cohort.get('end_date'),
            'session_week_day': group.get('session_week_day') or schedule_day_part(group.get('schedule')),
            'session_start_time': group.get('session_start_time') or schedule_time_parts(group.get('schedule'))[0],
            'session_end_time': group.get('session_end_time') or schedule_time_parts(group.get('schedule'))[1],
            'session_ksb_json': '[]',
            'notes': append_notes_meta(module.get('description') or '', meta),
            'is_archived': clean_str(module.get('status')).lower() == 'archived',
            'is_programme_deleted': is_programme_deleted,
            TRAINING_MODULE_CATALOGUE_COLUMN: module_id,
            'programme_display_order': None,
            'cohort_display_order': None,
            '_meta': meta,
        })
    return rows


def authoring_modules_as_catalogue_rows():
    try:
        module_rows = authoring_fetch_all(AUTHORING_MODULES_TABLE)
        week_rows = authoring_fetch_all(AUTHORING_WEEKS_TABLE)
    except (Exception, AssertionError):
        logger.debug('Could not build fallback module catalogue rows from authoring tables.', exc_info=True)
        return []

    week_names_by_module = defaultdict(list)
    ordered_weeks = sorted(
        week_rows,
        key=lambda item: (
            clean_str(item.get('module_catalogue_id')),
            parse_int(item.get('display_order'), 0),
            parse_int(item.get('week_number'), 0),
        ),
    )
    for week in ordered_weeks:
        title = week.get('title') or f'Week {week.get("week_number") or ""}'.strip()
        week_names_by_module[clean_str(week.get('module_catalogue_id'))].append(title)

    rows = []
    for module in module_rows:
        module_id = clean_str(module.get('module_catalogue_id'))
        session_names = unique(week_names_by_module.get(module_id) or [])
        rows.append({
            'Module ID': module_id,
            'Module_name': module.get('title') or f'Module {module_id}',
            'Number of sessions': module.get('sessions_number') or len(session_names),
            'start_date': module.get('start_date'),
            'end_date': module.get('end_date'),
            'Module_colour': module.get('color') or '#6941c6',
            'Notes': module.get('description') or '',
            'session_names_json': json_db_value(session_names),
            'session_ksb_json': '[]',
            'is_programme_deleted': programme_deleted_row(module),
        })
    return rows


def _notes_with_authoring_meta(module_row, programme_row=None, cohort_row=None, group_row=None):
    module_row = module_row or {}
    programme_row = programme_row or {}
    cohort_row = cohort_row or {}
    group_row = group_row or {}
    notes = clean_str(module_row.get('notes'))
    meta = {
        'program_id': module_row.get('programme_id') or programme_row.get('program_id'),
        'cohort_id': module_row.get('cohort_id') or cohort_row.get('cohort_id') or group_row.get('cohort_id'),
        'cohort_end_date': module_row.get('end_date') or cohort_row.get('end_date'),
        'group_id': module_row.get('group_id') or group_row.get('group_id'),
        'group_name': module_row.get('group_name') or group_row.get('group_name'),
        'coach_name': group_row.get('coach_name'),
        'module_catalogue_id': module_row.get('module_catalogue_id'),
        'module_color': module_row.get('color') or programme_row.get('color'),
    }
    meta_lines = [f'__{key}:{value}' for key, value in meta.items() if clean_str(value)]
    return '\n'.join([notes, *meta_lines]).strip()


def get_training_rows_from_authoring_tables():
    if not table_exists(AUTHORING_MODULES_TABLE):
        return []

    module_rows = fetch_all(f'''
        select *
        from {table_name(AUTHORING_MODULES_TABLE)}
        order by programme_id, cohort_name nulls last, group_name nulls last, start_date nulls last, title
    ''')
    programme_rows = fetch_all(f'select * from {table_name("programmes")}') if table_exists('programmes') else []
    cohort_rows = fetch_all(f'select * from {table_name("cohorts")}') if table_exists('cohorts') else []
    group_rows = fetch_all(f'select * from {table_name("groups")}') if table_exists('groups') else []

    programmes_by_id = {clean_str(row.get('program_id')): row for row in programme_rows if clean_str(row.get('program_id'))}
    cohorts_by_id = {clean_str(row.get('cohort_id')): row for row in cohort_rows if clean_str(row.get('cohort_id'))}
    groups_by_id = {clean_str(row.get('group_id')): row for row in group_rows if clean_str(row.get('group_id'))}

    rows = []
    for index, module in enumerate(module_rows, start=1):
        programme = programmes_by_id.get(clean_str(module.get('programme_id')), {})
        group = groups_by_id.get(clean_str(module.get('group_id')), {})
        cohort = cohorts_by_id.get(clean_str(module.get('cohort_id') or group.get('cohort_id')), {})
        is_programme_deleted = programme_deleted_row(module) or programme_deleted_row(group)
        programme_name = (
            clean_str(module.get('programme_name'))
            or clean_str(programme.get('name'))
            or clean_str(module.get('programme_id'))
            or 'Unassigned Programme'
        )
        cohort_name = clean_str(module.get('cohort_name')) or clean_str(cohort.get('cohort_name'))
        group_name = clean_str(module.get('group_name')) or clean_str(group.get('group_name'))
        start_date = module.get('start_date') or cohort.get('start_date')
        end_date = module.get('end_date') or cohort.get('end_date')
        status = clean_str(module.get('status') or programme.get('status')).lower()
        is_archived = (
            status == 'archived'
            or truthy(module.get('is_archived'))
            or truthy(programme.get('is_archived'))
            or falsey(programme.get('is_active'))
        )
        row = {
            'id': module.get('source_id') or module.get('module_catalogue_id') or index,
            'Program': programme_name,
            'module_name': module.get('title') or module.get('module_catalogue_id') or 'Module',
            'Cohort_name': cohort_name,
            'group_name': group_name,
            'status': clean_str(module.get('status') or programme.get('status') or 'draft').lower(),
            'Starting_date_lable': start_date,
            'start_date': start_date,
            'end_date': end_date,
            'sessions_number': parse_int(module.get('sessions_number'), 0),
            'session_week_day': clean_str(group.get('session_week_day') or schedule_day_part(group.get('schedule'))) or clean_str(group_name),
            'session_start_time': group.get('session_start_time') or schedule_time_parts(group.get('schedule'))[0],
            'session_end_time': group.get('session_end_time') or schedule_time_parts(group.get('schedule'))[1],
            'Tutor_name': '',
            'coach_name': group.get('coach_name') or '',
            'notes': _notes_with_authoring_meta(module, programme, cohort, group),
            'is_archived': is_archived,
            'is_programme_deleted': is_programme_deleted,
            'programme_display_order': None,
            'cohort_display_order': None,
            'session_ksb_json': '',
        }
        row['_meta'] = extract_notes_meta(row.get('notes'))
        rows.append(row)
    return rows


