@require_GET
def curriculum_ksb_trace(request, ksb_id):
    response = coverage_response(request)
    if response.status_code != 200:
        return response
    payload = json.loads(response.content)
    ident = coverage_normalise_code(ksb_id)
    item = next((
        row for row in payload.get('items', [])
        if coverage_normalise_code(row.get('code')) == ident
        or coverage_normalise_code(row.get('ksb_id') or row.get('ksbId')) == ident
    ), None)
    if not item:
        return json_error('KSB trace not found.', status=404)
    return JsonResponse(item)


@require_GET
def curriculum_readiness_validation(request):
    response = coverage_response(request, request.GET.get('scope') or '', request.GET.get('identifier') or '')
    if response.status_code != 200:
        return response
    payload = json.loads(response.content)
    # Readiness reports the one thing the weights state plainly: a KSB that is
    # required but carries no weight has nowhere to be taught. Weighted KSBs are
    # not judged against a 100% target, because no such target is defined.
    issues = []
    for item in payload.get('items', []):
        raw_weight = item.get('raw_total_weight') or 0
        if raw_weight <= 0:
            issues.append({
                'severity': 'warning',
                'code': item.get('code'),
                'raw_weight': raw_weight,
                'rawWeight': raw_weight,
                'message': f'{item.get("code")} is not mapped to any component.',
            })
    return JsonResponse({
        'ready': not issues,
        'canSaveDraft': True,
        'issues': issues,
        'summary': payload.get('summary'),
    })


