def update_staffing_assignment(identifier, payload):
    group_row = resolve_group_row(identifier)
    if not group_row:
        return json_error('Group not found for staffing assignment.', status=404)
    group_id = clean_str(group_row.get('group_id'))
    previous_coach = clean_str(group_row.get('coach_name'))

    # Same reasoning as the group PATCH: the coach write below lands before the
    # tutor is pushed onto the group's modules, so the refusal has to come first.
    if 'tutor' in payload and not tutor_conflict_override_requested(payload):
        candidate, conflicts = group_tutor_assignment_conflict(
            group_id,
            canonical_staff_assignment_name('tutor', payload.get('tutor')),
        )
        if conflicts:
            return tutor_conflict_error(candidate, conflicts)

    updates = {}
    if 'coach' in payload:
        updates['coach_name'] = canonical_staff_assignment_name('coach', payload.get('coach'))
    update_group_fields(group_id, updates)

    next_tutor = canonical_staff_assignment_name('tutor', payload.get('tutor')) if 'tutor' in payload else ''
    next_tutor_email = resolve_staff_assignment_email('tutor', next_tutor) if next_tutor else ''
    next_coach = canonical_staff_assignment_name('coach', payload.get('coach')) if 'coach' in payload else clean_str(group_row.get('coach_name'))
    module_assignment_ids = [
        clean_str(row.get('module_catalogue_id'))
        for row in safe_authoring_module_rows()
        if clean_str(row.get('group_id')) == group_id and row.get('module_catalogue_id')
    ]
    if 'tutor' in payload:
        for module_id in module_assignment_ids:
            update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_id], {
                'tutor_name': next_tutor or None,
                'tutor_email': next_tutor_email or None,
                'updated_at': datetime.utcnow(),
            })
    notify_staff_assignment_change()
    invalidate_curriculum_cache()
    return JsonResponse({'updated': True, 'id': group_id})


def find_staff_profile_row(role, identifier, include_archived=True):
    ident = clean_str(identifier)
    if not ident:
        return None
    rows = get_staff_profile_rows(role, include_archived=include_archived)
    for row in rows:
        if clean_str(row.get('id')) == ident:
            return row
    searchable_rows = [row for row in rows if not staff_profile_is_archived(row)] + [row for row in rows if staff_profile_is_archived(row)]
    email_key = normalise(ident)
    if email_key:
        for row in searchable_rows:
            if normalise(staff_profile_email(row)) == email_key:
                return row
    slug = slugify(ident)
    ident_key = staff_assignment_key(ident)
    for row in searchable_rows:
        name = staff_profile_name(row)
        if slugify(name) == slug or staff_assignment_key(name) == ident_key:
            return row
    return None


def clean_assignment_ids(values):
    seen = set()
    result = []
    for value in values or []:
        text = clean_str(value)
        if not text:
            continue
        expanded = [text]
        canonical_match = re.search(r'(MOD-[A-Z0-9][A-Z0-9_-]*)', text, re.IGNORECASE)
        if canonical_match:
            expanded.append(canonical_match.group(1))
        for item in expanded:
            if item in seen:
                continue
            seen.add(item)
            result.append(item)
    return result


def notify_staff_assignment_change():
    """Tell a tutor their assignment changed.

    This is all that is left of the old profile-link sync. Assignments live on
    ``curriculum.modules.tutor_name`` / ``curriculum.groups.coach_name``, and the
    staff themselves live in the directory, so there is no second copy to mirror
    a change into -- but the person still has to hear about it, and every write
    path that moves an assignment calls through here to make sure they do.
    """
    tutor_notifications.schedule_assignment_notifications()


def find_staff_user_profile(role, identifier):
    """One tutor or coach, by whichever identifier a caller has for them.

    An id, the staff user's uuid or row id, an email, or the name a module or
    group holds them under: a curriculum screen has only ever had one of those,
    and they all name the same person in the staff directory.
    """
    ident = clean_str(identifier)
    if not ident:
        return None
    profiles = build_staff_user_profile_collection(role, 'all')
    for profile in profiles:
        candidates = [
            clean_str(profile.get('id')),
            clean_str(profile.get('uuid')),
            clean_str(profile.get('staffUserId')),
        ]
        if ident in [value for value in candidates if value]:
            return profile
    email_key = normalise(ident)
    if email_key:
        for profile in profiles:
            if normalise(profile.get('email')) == email_key:
                return profile
    name_key = staff_assignment_key(ident)
    if name_key:
        for profile in profiles:
            if staff_assignment_key(profile.get('name')) == name_key:
                return profile
    return None


# Curriculum does not own staff records. Tutors and coaches are staff users an
# administrator invited and gave that access to, so the curriculum API reads them
# and never writes them: creating, renaming or deleting a person happens once, in
# Users, and every screen that shows them follows from there. These endpoints
# answer the reads and refuse the writes rather than quietly keeping a second
# copy of a person that the directory knows nothing about.
STAFF_PROFILE_READ_ONLY_MESSAGE = (
    'Tutors and coaches are managed in Users. Curriculum reads them from the staff '
    'directory and cannot create, change or delete them.'
)


